// The skeleton of the rig as procedural meshes: anatomical bones parented to the THREE.Bone that moves them (so they follow the pose with
// no per-frame work), joint markers coloured by degrees of freedom, landmark dots, a centre-of-mass marker, a selection ring with a
// local-frame triad and one arrow per DOF. Used by rig.js; pure three.js, no DOM, no WebGL needed to build it.
//
// Geometry. Every bone is ONE mesh (one draw call): the pieces (shaft, epiphyses, processes, ...) are generated by the small Mesher
// below, with vertex colours (bone, cartilage, discs, teeth, dark cavities), and concatenated into one BufferGeometry in the local frame
// of the joint that moves the bone (all frames are world aligned at rest, DESIGN.md 1.1, so local = neutral world - joint centre).
// Paired bones are built once for the LEFT side and mirrored (x -> -x, winding reversed) for the right. 118 bones (skeleton.js BONES)
// + 77 joint markers + a handful of overlay objects stay far below the 450 draw-call budget.
//
// Sizes. All shape dimensions are tabulated in metres for a 1.75 m person and multiplied by s = stature / 1.75; where a bone has
// its own length (femur, humerus, ...) the dimensions are written as ratios of that length (the ratios are in the comments next to the
// shape). Anatomical numbers are approximate textbook/atlas proportions (Gray's, Netter, Tilley & Dewey; Winter 2009 for the segment
// lengths): a medical-illustration skeleton, not a measured one.
import * as THREE from "three";
import { JOINTS, JOINT_BY_ID, BONES, BONE_BY_ID, REGIONS } from "./skeleton.js";

const V = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);
const X_ = V(1, 0, 0), Y_ = V(0, 1, 0), Z_ = V(0, 0, 1);
const D2R = Math.PI / 180;
const clamp01 = (t) => Math.min(1, Math.max(0, t));
const smooth = (t) => t * t * (3 - 2 * t);
const sgnpow = (x, e) => Math.sign(x) * Math.abs(x) ** e;

// ---------------------------------------------------------------------------------------------------------------------------------------
// Colours (sRGB hex; converted to the linear working space by THREE.Color)
export const COLORS = {
  bone: 0xa8967a, cartilage: 0x8aa3b8, disc: 0xbfa98c, tooth: 0xf8f3e6, cavity: 0x2d2723, eye: 0xefebe1, iris: 0x4a3b2f,
  root: 0xe5484d, dof1: 0x3b82f6, dof2: 0x22b573, dof3: 0xf59e0b, com: 0xe5484d,
};
const cc = (hex) => { const c = new THREE.Color(hex); return [c.r, c.g, c.b]; };

// ---------------------------------------------------------------------------------------------------------------------------------------
// Mesher: accumulates closed surface patches (grids of points) into one indexed geometry with normals and vertex colours.
export class Mesher {
  constructor(quality = 1) {
    this.q = quality;
    this.pos = [];
    this.nrm = [];
    this.col = [];
    this.idx = [];
    this.c = cc(COLORS.bone);
  }

  color(hex) { this.c = cc(hex); return this; }
  seg(n) { return Math.max(3, Math.round(n * this.q)); }

  /**
   * Add a grid of points rows[r][k] (Vector3). Columns wrap (a ring) unless wrapC is false; rows wrap if wrapR. A row whose points are
   * all the same is a pole (fan). The winding is fixed afterwards so that the surface of a CLOSED grid faces outward (signed volume > 0).
   */
  grid(rows, { wrapC = true, wrapR = false, closed = true } = {}) {
    const R = rows.length, C = rows[0].length, base = this.pos.length / 3;
    for (const row of rows) for (const p of row) this.pos.push(p.x, p.y, p.z);
    // typed scratch arrays and no per-triangle allocations: this loop and its garbage were a third of the whole skeleton build
    const P = this.pos, N = new Float64Array(R * C * 3), rEnd = wrapR ? R : R - 1, cEnd = wrapC ? C : C - 1;
    const tris = new Int32Array(Math.max(0, rEnd * cEnd * 6));
    let nt = 0;
    for (let r = 0; r < rEnd; r++) {
      const r2 = (r + 1) % R;
      for (let k = 0; k < cEnd; k++) {
        const k2 = (k + 1) % C;
        const a = r * C + k, b = r * C + k2, c = r2 * C + k, d = r2 * C + k2;
        tris[nt++] = a; tris[nt++] = b; tris[nt++] = c; tris[nt++] = b; tris[nt++] = d; tris[nt++] = c;
      }
    }
    // signed volume of the triangle soup: negative = inside out for a closed surface
    let vol = 0;
    const o = base * 3;
    for (let i = 0; i < nt; i += 3) {
      const a = o + tris[i] * 3, b = o + tris[i + 1] * 3, c = o + tris[i + 2] * 3;
      vol += P[a] * (P[b + 1] * P[c + 2] - P[b + 2] * P[c + 1]) - P[a + 1] * (P[b] * P[c + 2] - P[b + 2] * P[c]) + P[a + 2] * (P[b] * P[c + 1] - P[b + 1] * P[c]);
    }
    const flip = closed && vol < 0;
    const I = this.idx;
    for (let i = 0; i < nt; i += 3) {
      const a = tris[i], b = flip ? tris[i + 2] : tris[i + 1], c = flip ? tris[i + 1] : tris[i + 2];
      const pa = o + a * 3, pb = o + b * 3, pc = o + c * 3;
      const ux = P[pb] - P[pa], uy = P[pb + 1] - P[pa + 1], uz = P[pb + 2] - P[pa + 2];
      const vx = P[pc] - P[pa], vy = P[pc + 1] - P[pa + 1], vz = P[pc + 2] - P[pa + 2];
      const nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
      if (nx * nx + ny * ny + nz * nz < 1e-24) continue; // degenerate (pole fans)
      N[a * 3] += nx; N[a * 3 + 1] += ny; N[a * 3 + 2] += nz;
      N[b * 3] += nx; N[b * 3 + 1] += ny; N[b * 3 + 2] += nz;
      N[c * 3] += nx; N[c * 3 + 1] += ny; N[c * 3 + 2] += nz;
      I.push(base + a, base + b, base + c);
    }
    for (let i = 0; i < R * C; i++) {
      const l = Math.hypot(N[i * 3], N[i * 3 + 1], N[i * 3 + 2]) || 1;
      this.nrm.push(N[i * 3] / l, N[i * 3 + 1] / l, N[i * 3 + 2] / l);
      this.col.push(this.c[0], this.c[1], this.c[2]);
    }
    return this;
  }

  /** Ellipsoid (or superellipsoid when e < 1: boxier) at c with semi-axes r = [rx, ry, rz], rotated by q (local axes -> world); o.lower scales the lower half (flat base). */
  ellipsoid(c, r, q = null, o = {}) {
    const lat = o.lat ?? this.seg(8), lon = o.lon ?? this.seg(12), e = o.e ?? 1;
    const rows = [];
    for (let i = 0; i <= lat; i++) {
      const th = (Math.PI * i) / lat, st = Math.sin(th), ct = Math.cos(th), row = [];
      for (let k = 0; k < lon; k++) {
        const ph = (2 * Math.PI * k) / lon;
        const p = e === 1 ? V(r[0] * st * Math.cos(ph), r[1] * ct, r[2] * st * Math.sin(ph)) : V(r[0] * sgnpow(st, e) * sgnpow(Math.cos(ph), e), r[1] * sgnpow(ct, e), r[2] * sgnpow(st, e) * sgnpow(Math.sin(ph), e));
        if (o.lower != null && ct < 0) p.y *= o.lower;
        if (q) p.applyQuaternion(q);
        row.push(p.add(c));
      }
      rows.push(row);
    }
    return this.grid(rows);
  }

  /**
   * Generalised tube along a smooth curve through `path` (Vector3[]). prof(u) -> { a, b, ox, oy, pow, lobes } with u in [0,1] along the
   * curve: semi-axes a (along the section axis A) and b (along B = T x A), offset (ox, oy) of the section centre in that frame, super-ellipse
   * exponent pow (2 = ellipse), lobes = [k, amplitude] for a k-lobed (e.g. triangular) section. hint: Vector3 | (u, P, T) -> Vector3 giving
   * the direction of A (projected perpendicular to the tangent); without it A is parallel transported. capA / capB: dome height of the ends
   * as a fraction of the end radius (0 = flat). closed: a ring (no caps).
   */
  tube(path, prof, o = {}) {
    const segs = o.segs ?? this.seg(10), closed = !!o.closed;
    const straight = !closed && path.length === 2; // a rod: no curve to evaluate (CatmullRomCurve3 is the most expensive call of the whole skeleton build)
    const curve = straight ? null : new THREE.CatmullRomCurve3(path, closed, "centripetal");
    if (curve) curve.arcLengthDivisions = 48; // the default (200) costs more than the whole mesh for these short curves
    const n = o.n ?? Math.max(4, Math.round((o.density ?? 90) * (curve ? curve.getLength() : path[0].distanceTo(path[1])) * this.q)) + 1;
    // points at equal arc length (one curve evaluation each) and tangents as central differences of them: getTangentAt costs two more evaluations
    // per section, which was a third of the build time
    const P = straight ? Array.from({ length: n }, (_, j) => path[0].clone().lerp(path[1], j / (n - 1))) : curve.getSpacedPoints(closed ? n : n - 1).slice(0, n);
    const T = P.map((_, j) => {
      const a = P[closed ? (j + n - 1) % n : Math.max(0, j - 1)], b = P[closed ? (j + 1) % n : Math.min(n - 1, j + 1)];
      return b.clone().sub(a).normalize();
    });
    const hintAt = typeof o.hint === "function" ? o.hint : o.hint ? () => o.hint : null;
    const frames = [];
    let prevA = null;
    for (let j = 0; j < n; j++) {
      const u = closed ? j / n : j / (n - 1), t = T[j];
      let A = null;
      if (hintAt) { const h = hintAt(u, P[j], t); A = h.clone().addScaledVector(t, -h.dot(t)); if (A.lengthSq() < 1e-6) A = null; }
      if (!A) {
        if (prevA) { A = prevA.clone().addScaledVector(t, -prevA.dot(t)); }
        if (!A || A.lengthSq() < 1e-6) { const w = Math.abs(t.y) < 0.9 ? Y_ : X_; A = w.clone().addScaledVector(t, -w.dot(t)); }
      }
      A.normalize();
      prevA = A;
      frames.push({ A, B: new THREE.Vector3().crossVectors(t, A) });
    }
    const section = (j, u, scale = 1, shift = 0, rowOut) => {
      const pr = prof(u), { A, B } = frames[j], row = [];
      const a = pr.a * scale, b = (pr.b ?? pr.a) * scale, pw = 2 / (pr.pow ?? 2);
      for (let k = 0; k < segs; k++) {
        const ph = (2 * Math.PI * k) / segs;
        let cx = sgnpow(Math.cos(ph), pw), cy = sgnpow(Math.sin(ph), pw);
        if (pr.lobes) { const m = 1 + pr.lobes[1] * Math.cos(pr.lobes[0] * ph + (pr.lobes[2] ?? 0)); cx *= m; cy *= m; }
        row.push(P[j].clone().addScaledVector(A, a * cx + (pr.ox ?? 0)).addScaledVector(B, b * cy + (pr.oy ?? 0)).addScaledVector(T[j], shift));
      }
      rowOut.push(row);
    };
    const rows = [];
    const cap = (j, u, dir, dome) => {
      const pr = prof(u), r = Math.max(pr.a, pr.b ?? pr.a), h = dome * r;
      const al = [1.38, 1.08, 0.75, 0.38]; // dome steps (radians from the pole)
      const tmp = [];
      for (const x of al) section(j, u, Math.cos(x) < 0 ? 0 : Math.cos(x), dir * Math.sin(x) * h, tmp);
      // pole
      const pole = P[j].clone().addScaledVector(T[j], dir * h).addScaledVector(frames[j].A, pr.ox ?? 0).addScaledVector(frames[j].B, pr.oy ?? 0);
      return [new Array(segs).fill(0).map(() => pole.clone()), ...tmp];
    };
    if (closed) {
      for (let j = 0; j < n; j++) section(j, j / n, 1, 0, rows);
      return this.grid(rows, { wrapR: true });
    }
    const d0 = o.capA ?? 0.5, d1 = o.capB ?? 0.5;
    if (d0 >= 0) rows.push(...(d0 > 0 ? cap(0, 0, -1, d0) : [(() => { const pr = prof(0); const pole = P[0].clone().addScaledVector(frames[0].A, pr.ox ?? 0).addScaledVector(frames[0].B, pr.oy ?? 0); return new Array(segs).fill(0).map(() => pole.clone()); })()]));
    for (let j = 0; j < n; j++) section(j, j / (n - 1), 1, 0, rows);
    if (d1 >= 0) {
      if (d1 > 0) rows.push(...cap(n - 1, 1, 1, d1).reverse());
      else { const pr = prof(1); const pole = P[n - 1].clone().addScaledVector(frames[n - 1].A, pr.ox ?? 0).addScaledVector(frames[n - 1].B, pr.oy ?? 0); rows.push(new Array(segs).fill(0).map(() => pole.clone())); }
    }
    return this.grid(rows);
  }

  /** Straight tapered rod from a to b with semi-axes (rA, rB) at a and (rA2, rB2) at b (default: the same). */
  rod(a, b, ra, rb = ra, ra2 = ra, rb2 = rb, o = {}) {
    return this.tube([a, b], (u) => ({ a: ra + (ra2 - ra) * u, b: rb + (rb2 - rb) * u, pow: o.pow }), { hint: o.hint, capA: o.capA ?? 0.6, capB: o.capB ?? 0.6, segs: o.segs, n: 3 });
  }

  /**
   * Thick plate over a parametric surface S(u, v) -> Vector3 (the mid surface): perim = [[u, v], ...] a closed outline (star-shaped about
   * c = [u, v]); thick(u, v) = full thickness; mid = fraction of the thickness at the centre (thin middle, thick rim). Solid with a
   * rounded rim: rows run bottom pole -> rings out to the rim -> rings back on the top face -> top pole.
   */
  plate(S, perim, c, thick, o = {}) {
    const R = o.rings ?? this.seg(5), mid = o.mid ?? 0.45, e = 1e-3;
    const nrm = (u, v) => {
      const p = S(u, v), pu = S(u + e, v).sub(p), pv = S(u, v + e).sub(p);
      const n = pu.cross(pv);
      if (n.lengthSq() < 1e-18) { const q = S(u - e, v - e); const m = S(u, v).sub(q).cross(pv); return m.lengthSq() < 1e-18 ? V(0, 0, 1) : m.normalize(); }
      return n.normalize();
    };
    const at = (r, h) => perim.map(([pu, pv]) => {
      const u = c[0] + (pu - c[0]) * r, v = c[1] + (pv - c[1]) * r;
      const t = thick(u, v) * (mid + (1 - mid) * r * r) * h;
      return S(u, v).addScaledVector(nrm(u, v), t / 2);
    });
    const rows = [at(0, -1)];
    for (let i = 1; i <= R; i++) rows.push(at(i / R, -1));
    rows.push(at(1 + 0.012, 0));
    for (let i = R; i >= 1; i--) rows.push(at(i / R, 1));
    rows.push(at(0, 1));
    return this.grid(rows);
  }

  /** Concatenate into a BufferGeometry in the frame of `origin` (neutral world position of the joint); mirror: x -> -x and winding reversed. */
  build(origin, mirror = false) {
    const n = this.pos.length / 3;
    const pos = new Float32Array(n * 3), nrm = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) {
      const x = this.pos[3 * i] - origin.x, y = this.pos[3 * i + 1] - origin.y, z = this.pos[3 * i + 2] - origin.z;
      pos[3 * i] = mirror ? -x : x; pos[3 * i + 1] = y; pos[3 * i + 2] = z;
      nrm[3 * i] = mirror ? -this.nrm[3 * i] : this.nrm[3 * i]; nrm[3 * i + 1] = this.nrm[3 * i + 1]; nrm[3 * i + 2] = this.nrm[3 * i + 2];
    }
    const idx = n > 65535 ? new Uint32Array(this.idx) : new Uint16Array(this.idx);
    if (mirror) for (let i = 0; i < idx.length; i += 3) { const t = idx[i + 1]; idx[i + 1] = idx[i + 2]; idx[i + 2] = t; }
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
    g.setAttribute("normal", new THREE.BufferAttribute(nrm, 3));
    g.setAttribute("color", new THREE.BufferAttribute(new Float32Array(this.col), 3));
    g.setIndex(new THREE.BufferAttribute(idx, 1));
    g.computeBoundingSphere();
    g.computeBoundingBox();
    return g;
  }
}

/** Rotation whose columns are the given orthonormal, right-handed axes (local X -> x, Y -> y, Z -> z). */
export const basisQ = (x, y, z) => new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(x, y, z));
/** Quaternion taking local +Y to `dir` and (as far as possible) local +Z to `fwd`. */
export function frameQ(dir, fwd = Z_) {
  const y = dir.clone().normalize();
  let z = fwd.clone().addScaledVector(y, -fwd.dot(y));
  if (z.lengthSq() < 1e-8) z = (Math.abs(y.x) < 0.9 ? X_ : Z_).clone().addScaledVector(y, -(Math.abs(y.x) < 0.9 ? y.x : y.z));
  z.normalize();
  const x = new THREE.Vector3().crossVectors(y, z);
  return new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(x, y, z));
}

// ---------------------------------------------------------------------------------------------------------------------------------------
// Anatomical shapes. Written for the LEFT side in neutral world coordinates (metres); `ctx` gives s (scale), the joint / landmark
// lookups and the vertebra geometry. Lengths are m at 1.75 m times s unless a ratio of the bone's own length is stated.
const CHAIN = [...REGIONS.lumbar.joints, ...REGIONS.thoracic.joints, ...REGIONS.cervical.joints, "head"]; // L5 .. C1, head
const num = (id) => +id.slice(1);
const tab = (a, i) => a[Math.min(a.length - 1, Math.max(0, i))];
// vertebral body width, depth (m at 1.75) by level (after Panjabi et al. 1991 / Gray's, rounded; approx.)
const VB = {
  C: { w: [0, 0, 0.017, 0.0175, 0.018, 0.020, 0.025], d: [0, 0, 0.0155, 0.016, 0.0165, 0.017, 0.0175], disc: 0.24 },
  T: { w: [0, 0.026, 0.0265, 0.027, 0.028, 0.030, 0.032, 0.034, 0.036, 0.038, 0.040, 0.0415, 0.043], d: [0, 0.019, 0.020, 0.021, 0.022, 0.023, 0.0245, 0.026, 0.027, 0.0285, 0.030, 0.031, 0.031], disc: 0.20 },
  L: { w: [0, 0.044, 0.047, 0.049, 0.051, 0.052], d: [0, 0.030, 0.031, 0.032, 0.033, 0.033], disc: 0.26 },
};
// spinous process: [length, drop angle (deg below horizontal)] by level
const SPIN = { C3: [0.018, 8], C4: [0.019, 8], C5: [0.020, 8], C6: [0.022, 10], C7: [0.040, 15], T1: [0.040, 20], T2: [0.040, 35], T3: [0.041, 40], T4: [0.043, 52], T5: [0.044, 56], T6: [0.044, 58], T7: [0.044, 58], T8: [0.043, 56], T9: [0.042, 50], T10: [0.038, 38], T11: [0.033, 22], T12: [0.030, 12], L1: [0.034, 6], L2: [0.036, 4], L3: [0.036, 4], L4: [0.034, 2], L5: [0.028, 0], C2: [0.028, 10] };

/** Geometry of a vertebra in the neutral pose: frame (u up, f forward, l left), body centre and size, canal centre, arch radii. */
function vertGeom(W, id, s) {
  const k = CHAIN.indexOf(id), B = W[id], T = W[CHAIN[k + 1]];
  const u = T.clone().sub(B), pitch = u.length();
  u.divideScalar(pitch);
  const f = X_.clone().cross(u).normalize(), l = u.clone().cross(f);
  const reg = id[0], n = num(id), tb = VB[reg] ?? VB.C;
  const g = { id, reg, n, B, T, u, f, l, pitch, Bc: B.clone().lerp(T, 0.5), s };
  g.w = tab(tb.w, n) * s; g.d = tab(tb.d, n) * s;
  if (id === "C2") { g.w = 0.0225 * s; g.d = 0.019 * s; }
  g.dFrac = id === "C2" ? 0.10 : tb.disc; // the C1/C2 joint has no disc, C2 carries the dens
  g.disc = pitch * g.dFrac;
  g.hb = pitch - g.disc; // body height
  const cn = reg === "L" ? [0.0145, 0.0125] : reg === "T" ? [0.0090, 0.0095] : [0.0125, 0.0105];
  g.cw = cn[0] * s; g.cd = cn[1] * s;
  g.cwo = g.cw + 0.004 * s; g.cdo = g.cd + 0.004 * s; // centre line of the neural arch
  g.Cc = g.Bc.clone().addScaledVector(f, -(g.d / 2 + 0.002 * s + g.cd)); // canal centre
  g.arch = (ang) => g.Cc.clone().addScaledVector(l, g.cwo * Math.cos(ang)).addScaledVector(f, -g.cdo * Math.sin(ang)); // 0 = left, pi/2 = back midline
  // transverse process tip (left): [length, backward shift, up shift]
  const tp = reg === "L" ? [0.036 + 0.002 * (3 - Math.abs(3 - n)), 0.003, 0] : reg === "T" ? [0.026 - 0.0008 * (n - 1), 0.012, 0.0] : [id === "C7" ? 0.022 : 0.016, -0.004, -0.003];
  g.tpTip = g.arch(0.12).addScaledVector(l, tp[0] * s).addScaledVector(f, -tp[1] * s).addScaledVector(u, tp[2] * s);
  return g;
}

function buildVertebra(ctx, def, m) {
  const g = ctx.vg[def.level], s = ctx.s;
  if (def.level === "C1") return atlas(ctx, g, m);
  const { u, f, l, Bc, B, hb } = g, D2 = g.d / 2, W2 = g.w / 2;
  // body: waisted, rounded elliptical column (width, depth: tables above; height = pitch minus the disc)
  m.color(COLORS.bone);
  m.tube([Bc.clone().addScaledVector(u, -hb / 2), Bc.clone().addScaledVector(u, hb / 2)], (t) => {
    const mm = 0.90 + 0.10 * (2 * t - 1) ** 2 - 0.06 * (t < 0.03 || t > 0.97 ? 1 : 0);
    return { a: D2 * mm, b: W2 * mm, pow: 2.4 };
  }, { hint: f, capA: 0.16, capB: 0.16, n: 6, segs: m.seg(14) });
  if (def.level !== "C1") {
    m.color(COLORS.disc);
    m.tube([B.clone().addScaledVector(u, -g.disc / 2), B.clone().addScaledVector(u, g.disc / 2)], () => ({ a: D2 * 1.05, b: W2 * 1.05, pow: 2.4 }), { hint: f, capA: 0.12, capB: 0.12, n: 3, segs: m.seg(14) });
    m.color(COLORS.bone);
  }
  // neural arch: pedicle - lamina - pedicle as one swept ring segment behind the body
  const pedL = Bc.clone().addScaledVector(l, W2 * 0.55).addScaledVector(f, -D2 * 0.8), pedR = Bc.clone().addScaledVector(l, -W2 * 0.55).addScaledVector(f, -D2 * 0.8);
  const arc = [0, 0.4, 0.8, 1.2, Math.PI / 2, Math.PI - 1.2, Math.PI - 0.8, Math.PI - 0.4, Math.PI].map((a) => g.arch(a));
  const path = [pedL, ...arc, pedR];
  m.tube(path, (t) => {
    const ped = smooth(clamp01(1 - Math.min(t, 1 - t) / 0.16)); // 1 at the pedicles, 0 along the lamina
    return { a: hb * (0.42 - 0.20 * ped) / 1, b: (0.0036 + 0.0014 * ped) * s, pow: 2.6 };
  }, { hint: u, capA: 0.3, capB: 0.3, segs: m.seg(8), density: 140 });
  // spinous process
  const [sl, sa] = SPIN[def.level] ?? [0.03, 10];
  const S0 = g.arch(Math.PI / 2), ang = (sa * Math.PI) / 180;
  const S1 = S0.clone().addScaledVector(f, -sl * s * Math.cos(ang)).addScaledVector(u, -sl * s * Math.sin(ang));
  m.rod(S0.clone().addScaledVector(f, 0.003 * s), S1, hb * 0.34, 0.0030 * s, hb * 0.20, 0.0022 * s, { hint: u, segs: m.seg(7), capB: 0.7 });
  // transverse processes with a bulb at the tip (the costal facet of thoracic vertebrae)
  for (const sd of [1, -1]) {
    const mir = (p) => (sd === 1 ? p : Bc.clone().add(p.clone().sub(Bc).sub(l.clone().multiplyScalar(2 * p.clone().sub(Bc).dot(l)))));
    const J0 = mir(g.arch(0.12)), tip = mir(g.tpTip);
    const tk = def.level[0] === "L" ? 1.55 : 1;
    m.rod(J0, tip, 0.0046 * s * tk, 0.0040 * s * tk, 0.0036 * s * tk, 0.0034 * s * tk, { hint: u, segs: m.seg(7) });
    if (def.level[0] === "T") m.ellipsoid(tip, [0.0042 * s, 0.0048 * s, 0.0050 * s], frameQ(u, f), { lat: m.seg(5), lon: m.seg(7) });
    // articular processes: superior and inferior, beside the canal
    for (const dir of [1, -1]) m.ellipsoid(mir(g.arch(0.25)).addScaledVector(u, dir * hb * 0.40), [0.0065 * s, 0.0078 * s, 0.0050 * s], frameQ(u, f), { lat: m.seg(5), lon: m.seg(7) });
  }
  if (def.level === "C2") { // dens: the peg that rises into the ring of the atlas
    const top = B.clone().addScaledVector(g.u, g.pitch);
    m.rod(top.clone().addScaledVector(u, -g.hb * 0.4), top.clone().addScaledVector(u, 0.013 * s), 0.0050 * s, 0.0050 * s, 0.0040 * s, 0.0040 * s, { capB: 0.8, segs: m.seg(9) });
    for (const sd of [1, -1]) m.ellipsoid(top.clone().addScaledVector(l, sd * 0.0155 * s).addScaledVector(u, -0.003 * s), [0.0100 * s, 0.0040 * s, 0.0120 * s], frameQ(u, f), { lat: m.seg(5), lon: m.seg(8) }); // superior facets
  }
  return m;
}

function atlas(ctx, g, m) {
  const { u, f, l, s } = ctx.vg.C1;
  const c = g.B.clone().addScaledVector(u, g.pitch * 0.5);
  const ring = [];
  for (let i = 0; i < 12; i++) { const a = (2 * Math.PI * i) / 12; ring.push(c.clone().addScaledVector(l, 0.0185 * s * Math.cos(a)).addScaledVector(f, 0.0155 * s * Math.sin(a))); }
  m.tube(ring, (t) => ({ a: 0.0072 * s, b: 0.0042 * s, pow: 2.6 }), { closed: true, hint: u, segs: m.seg(8), density: 200 });
  for (const sd of [1, -1]) {
    m.ellipsoid(c.clone().addScaledVector(l, sd * 0.0195 * s), [0.0110 * s, 0.0090 * s, 0.0125 * s], frameQ(u, f), { lat: m.seg(6), lon: m.seg(9) }); // lateral masses
    m.rod(c.clone().addScaledVector(l, sd * 0.024 * s), c.clone().addScaledVector(l, sd * 0.038 * s).addScaledVector(f, -0.004 * s), 0.0055 * s, 0.0040 * s, 0.0040 * s, 0.0032 * s, { hint: u, segs: m.seg(6) });
  }
  m.ellipsoid(c.clone().addScaledVector(f, -0.0185 * s), [0.0050 * s, 0.0055 * s, 0.0050 * s], null, { lat: m.seg(5), lon: m.seg(6) }); // posterior tubercle
  return m;
}

// Sacrum + coccyx. A curved wedge from the L5/S1 joint down and back: wide and thick at the base, concave in front, with the promontory at the
// front of the base and the ala spreading to both sides; 95 mm along the axis (plus 36 mm of coccyx) at 1.75 m. It is anchored to the joint
// L5, the PSIS and the ischial tuberosity landmarks, NOT to the pelvis joint: the pelvis joint is a root whose position differs between
// bodies (fit.js puts it at hip height, 126 mm below L5; the first synthetic body had it at S2/S3, 50 mm below), and a length taken from
// |L5 - pelvis| made the sacrum 277 mm long on fitted bodies, ending in a spike between the thighs. The tilt of the axis puts the apex
// half way between the PSIS and the ischium in front-to-back position, within 5-40 degrees of vertical.
function buildSacrum(ctx, def, m) {
  const s = ctx.s, A = ctx.J("L5");
  const psis = ctx.LM.PSIS_L ?? ctx.LM.psis_L, isch = ctx.LM.ischial_L;
  const Ls = isch ? Math.min(0.095 * s, Math.max(0.07 * s, 0.55 * (A.y - isch.y))) : 0.095 * s;
  const zT = psis && isch ? (psis.z + isch.z) / 2 : A.z - Ls * Math.sin(25 * D2R);
  const sinT = Math.min(Math.sin(40 * D2R), Math.max(Math.sin(5 * D2R), (A.z - zT) / Ls));
  const d = V(0, -Math.sqrt(1 - sinT * sinT), -sinT); // down along the sacrum (and back)
  const f = V(0, -sinT, Math.sqrt(1 - sinT * sinT)); // forward, perpendicular to d
  const l = X_.clone();
  const Sb = A.clone().addScaledVector(d, 0.004 * s);
  const at = (t, back = 0) => Sb.clone().addScaledVector(d, Ls * t).addScaledVector(f, -back);
  const bow = [0, 0.006, 0.013, 0.017, 0.014].map((v) => v * s);
  const pts = [0, 0.25, 0.5, 0.75, 1].map((t, i) => at(t, bow[i]));
  m.tube(pts, (t) => ({ a: (0.020 - 0.013 * smooth(t)) * s, b: (0.050 - 0.038 * smooth(Math.min(1, t * 1.15))) * s, pow: 3 }), { hint: f, capA: 0.3, capB: 0.5, segs: m.seg(16), density: 130 });
  for (const sd of [1, -1]) { // ala
    m.ellipsoid(Sb.clone().addScaledVector(l, sd * 0.034 * s).addScaledVector(d, 0.012 * s).addScaledVector(f, -0.008 * s), [0.020 * s, 0.011 * s, 0.026 * s], frameQ(d.clone().negate(), f), { lat: m.seg(6), lon: m.seg(10) });
    // sacral foramina: two dark rows on the front (hint of the anterior sacral foramina)
    m.color(COLORS.cavity);
    [0.2, 0.4, 0.58, 0.74].forEach((t, i) => m.ellipsoid(at(t, bow[Math.min(4, Math.round(t * 4))] * 0.95).addScaledVector(f, 0.012 * s * (1 - 0.6 * t)).addScaledVector(l, sd * (0.019 - 0.012 * t) * s), [0.0035 * s, 0.0035 * s, 0.0022 * s], frameQ(d, f), { lat: 4, lon: 6 }));
    m.color(COLORS.bone);
  }
  m.ellipsoid(Sb.clone().addScaledVector(f, 0.012 * s).addScaledVector(d, -0.004 * s), [0.017 * s, 0.006 * s, 0.009 * s], frameQ(d, f), { lat: m.seg(5), lon: m.seg(8) }); // promontory
  // coccyx: four fused segments curving forward
  const apex = at(1, bow[4]);
  const cc = [apex, apex.clone().addScaledVector(d, 0.014 * s).addScaledVector(f, 0.001 * s), apex.clone().addScaledVector(d, 0.027 * s).addScaledVector(f, 0.008 * s), apex.clone().addScaledVector(d, 0.036 * s).addScaledVector(f, 0.017 * s)];
  m.tube(cc, (t) => ({ a: (0.0065 - 0.0040 * t) * s, b: (0.0090 - 0.0060 * t) * s }), { hint: f, segs: m.seg(7), capB: 0.5 });
  return m;
}

// Hip bone (left): ilium wing as a curved plate between the iliac crest and the acetabular roof, the pubis and ischium as a flat strap around the
// obturator foramen (a ribbon lying in the plane of the foramen, thick at the ischial tuberosity), the acetabular rim around the hip joint.
// Key points relative to the hip joint centre (m at 1.75), z forward, x lateral.
function loopNormal(pts) { // Newell's method: normal of a closed (roughly planar) polygon
  const n = V();
  for (let i = 0; i < pts.length; i++) { const a = pts[i], b = pts[(i + 1) % pts.length]; n.x += (a.y - b.y) * (a.z + b.z); n.y += (a.z - b.z) * (a.x + b.x); n.z += (a.x - b.x) * (a.y + b.y); }
  return n.normalize();
}
function buildInnominate(ctx, def, m) {
  const s = ctx.s, H = ctx.J("hip");
  const p = (x, y, z) => H.clone().add(V(x * s, y * s, z * s));
  const crest = [p(0.036, 0.084, 0.050), p(0.062, 0.102, 0.030), p(0.074, 0.106, -0.005), p(0.060, 0.102, -0.040), p(0.020, 0.094, -0.075), p(-0.044, 0.088, -0.100)];
  const low = [p(0.022, 0.036, 0.044), p(0.020, 0.026, 0.024), p(0.018, 0.022, -0.002), p(0.006, 0.016, -0.040), p(-0.012, 0.026, -0.072), p(-0.042, 0.048, -0.096)];
  // The template above (a 1.75 m body, m relative to the hip joint) is warped so that the bony landmarks of the body lie on the bone: the front end
  // of the crest follows the ASIS, the back end the PSIS (which is where the sacrum meets it: without this the wings float away from the sacrum
  // when a body's pelvis is not the template's), the top of the crest the iliocristale. Landmarks are skin points: the bone is ~1 cm inside.
  const lmA = ctx.LM.ASIS_L ?? ctx.LM.asis_L, lmP = ctx.LM.PSIS_L ?? ctx.LM.psis_L, lmC = ctx.LM.iliocristale_L;
  const into = (q, dx, dy, dz) => (q ? q.clone().add(V(dx * s, dy * s, dz * s)) : null);
  const dA = lmA ? into(lmA, -0.008, -0.004, 0.002).sub(crest[0]) : V(), dP = lmP ? into(lmP, 0.002, -0.006, 0.014).sub(crest[5]) : V();
  const dC = lmC ? into(lmC, -0.010, -0.010, 0).sub(crest[2]).sub(dA.clone().lerp(dP, 0.4)) : V();
  crest.forEach((q, i) => q.add(dA.clone().lerp(dP, i / 5)).addScaledVector(dC, Math.exp(-(((i / 5 - 0.4) / 0.28) ** 2))));
  low.forEach((q, i) => q.addScaledVector(dA.clone().lerp(dP, i / 5), smooth(Math.abs(2 * (i / 5) - 1))));
  const cc = new THREE.CatmullRomCurve3(crest, false, "centripetal"), lc = new THREE.CatmullRomCurve3(low, false, "centripetal");
  const S = (u, v) => cc.getPoint(clamp01(u)).lerp(lc.getPoint(clamp01(u)), v);
  const perim = [], N = m.seg(10);
  for (let i = 0; i <= N; i++) perim.push([i / N, 0]);
  for (let i = 1; i <= 4; i++) perim.push([1, i / 5]);
  for (let i = N; i >= 0; i--) perim.push([i / N, 1]);
  for (let i = 4; i >= 1; i--) perim.push([0, i / 5]);
  m.plate(S, perim, [0.5, 0.5], () => 0.014 * s, { rings: m.seg(6), mid: 0.30 });
  // obturator frame: acetabular front -> superior ramus -> symphysis -> inferior ramus -> tuberosity -> spine -> back of the acetabulum
  const loop = [p(0.012, 0.012, 0.030), p(-0.020, 0.002, 0.052), p(-0.062, -0.002, 0.056), p(-0.082, -0.018, 0.050), p(-0.072, -0.050, 0.040), p(-0.052, -0.074, 0.010), p(-0.034, -0.088, -0.035), p(-0.010, -0.060, -0.052), p(0.004, -0.020, -0.045), p(0.014, 0.006, -0.020)];
  const nO = loopNormal(loop);
  const bump = (t, c, w) => Math.exp(-(((t - c) / w) ** 2));
  m.tube(loop, (t) => ({ a: (0.0042 + 0.0030 * bump(t, 0.62, 0.10)) * s, b: (0.0090 + 0.0045 * bump(t, 0.62, 0.12) + 0.0030 * bump(t, 0.1, 0.08)) * s, pow: 2.6 }), { closed: true, hint: nO, segs: m.seg(9), density: 220 });
  m.ellipsoid(p(-0.014, -0.040, -0.030), [0.0145 * s, 0.030 * s, 0.017 * s], null, { lat: m.seg(6), lon: m.seg(9) }); // body of the ischium
  m.ellipsoid(p(-0.080, -0.014, 0.050), [0.0105 * s, 0.0190 * s, 0.0120 * s], null, { lat: m.seg(6), lon: m.seg(9) }); // body of the pubis / symphysis face
  // acetabular rim: a flat ring around the axis the socket faces (lateral, a little forward and down)
  const nA = V(0.80, -0.35, 0.48).normalize(), e1 = new THREE.Vector3().crossVectors(nA, Y_).normalize(), e2 = new THREE.Vector3().crossVectors(nA, e1);
  const rim = [];
  for (let i = 0; i < 14; i++) { const a = (2 * Math.PI * i) / 14; rim.push(H.clone().addScaledVector(nA, 0.004 * s).addScaledVector(e1, 0.0290 * s * Math.cos(a)).addScaledVector(e2, 0.0290 * s * Math.sin(a))); }
  m.tube(rim, () => ({ a: 0.0062 * s, b: 0.0050 * s, pow: 2.4 }), { closed: true, hint: nA, segs: m.seg(7), density: 260 });
  m.ellipsoid(crest[0], [0.0090 * s, 0.0090 * s, 0.0090 * s], null, { lat: m.seg(5), lon: m.seg(8) }); // ASIS
  m.ellipsoid(crest[5], [0.0100 * s, 0.0100 * s, 0.0090 * s], null, { lat: m.seg(5), lon: m.seg(8) }); // PSIS
  m.ellipsoid(p(-0.034, -0.090, -0.036), [0.0120 * s, 0.0100 * s, 0.0130 * s], null, { lat: m.seg(6), lon: m.seg(8) }); // ischial tuberosity
  return m;
}

// Sternum: manubrium, body, xiphoid as one flat swept shape along the line from the suprasternale to the xiphoid, set 16 mm behind the
// skin landmarks; half-width 27 mm at the top, 14 mm in the body (with a small scallop at every costal notch), tapering to the xiphoid tip.
function sternumFrame(ctx) {
  const sup = ctx.L("suprasternale"), xi = ctx.L("xiphoid"), s = ctx.s;
  const len = xi.distanceTo(sup), dir = xi.clone().sub(sup).divideScalar(len);
  const N = dir.clone().cross(X_).normalize(); // forward
  const at = (t) => sup.clone().addScaledVector(dir, t * len).addScaledVector(N, -0.016 * s);
  return { sup, xi, len, dir, N, at };
}
const RIB_ST = [0.04, 0.27, 0.38, 0.48, 0.58, 0.68, 0.78]; // fraction of the sternum length at which rib 1..7 attaches (manubrium, angle, body)
/** Half-width (m at 1.75) of the sternum at the fraction t of its length: 27 mm at the top, 14-15 mm in the body, a notch at each costal cartilage, tapering to the xiphoid. */
function sternumHalfWidth(t) {
  let b = t < 0.27 ? 0.027 - 0.007 * smooth(t / 0.27) : t < 0.86 ? 0.0148 + 0.0010 * ((t - 0.27) / 0.59) : 0.012 * (1 - smooth((t - 0.86) / 0.14)) + 0.003;
  if (t >= 0.27 && t < 0.86) for (const f of RIB_ST.slice(2)) b -= 0.0016 * Math.exp(-(((t - f) / 0.03) ** 2)); // small notch at each costal cartilage
  return b;
}
function buildSternum(ctx, def, m) {
  const { N, at } = sternumFrame(ctx), s = ctx.s;
  const path = [0, 0.14, 0.27, 0.45, 0.65, 0.84, 0.90, 1].map(at);
  m.tube(path, (t) => ({ a: (t < 0.27 ? 0.0066 : t < 0.86 ? 0.0050 : 0.0036) * s, b: sternumHalfWidth(t) * s, pow: 3 }), { hint: N, capA: 0.5, capB: 0.8, segs: m.seg(10), density: 130 });
  return m;
}

// Ribs. Rib n (parented to the joint T_n): head on the upper body of T_n, neck to the transverse process, then a plan-view arc
// x = W sin(a), z = zc - D cos(a) around the chest to the front, descending toward the front (y falls with u^1.25), ending near the
// sternal border (ribs 1-7: costal cartilage up to the sternum; 8-10: cartilage up to the rib above; 11-12 free). W (half-breadth at the rib, m at 1.75,
// scaled by the shoulder breadth), D and zc follow from the tubercle and the anterior end, so the ribcage fits the vertebrae and the sternum of the body.
const RIB_W = [0, 0.050, 0.075, 0.098, 0.115, 0.127, 0.136, 0.143, 0.148, 0.150, 0.148, 0.138, 0.118];
const RIB_DROP = [0, 0.0, 0.010, 0.020, 0.030, 0.038, 0.045, 0.050];
const RIB_RUN = [0, 0.016, 0.030, 0.038, 0.052, 0.064, 0.074, 0.084]; // from the sternal border to the end of the bony rib; ribs 1-2 are longer so that their cartilage shows
function ribPlan(ctx, n) {
  const s = ctx.s, cs = ctx.cs, g = ctx.vg[`T${n}`], st = sternumFrame(ctx);
  const head = g.Bc.clone().addScaledVector(g.u, g.hb * 0.28).addScaledVector(g.l, g.w * 0.5 + 0.001 * s).addScaledVector(g.f, -g.d * 0.12);
  const tub = g.tpTip.clone().addScaledVector(g.l, -0.004 * s).addScaledVector(g.f, -0.0005 * s); // tubercle at the transverse process
  const Wn = RIB_W[n] * s * cs;
  const x1 = tub.x, z1 = tub.z, y1 = tub.y - 0.002 * s;
  let a1 = Math.asin(Math.min(0.95, x1 / Wn)), A = null, a2, zc, D, yA;
  if (n <= 10) {
    if (n <= 7) {
      const t = RIB_ST[n - 1], c = st.at(t), run = RIB_RUN[n] * s * cs;
      A = V(sternalEdge(t, s) + run, c.y - RIB_DROP[n] * s, c.z - 0.3 * run - 0.004 * s);
    } else {
      const A7 = ribPlan(ctx, 7).A, k = n - 7;
      const xa = [0, 0.100, 0.116, 0.124][k] * s * cs, dy = [0, 0.030, 0.062, 0.092][k] * s, dz = [0, 0.014, 0.036, 0.060][k] * s;
      A = V(xa, A7.y - dy, A7.z - dz);
    }
    const xa = Math.min(A.x, Wn * 0.985);
    a2 = Math.PI - Math.asin(xa / Wn);
    const c1 = Math.cos(a1), c2 = Math.cos(Math.PI - a2);
    D = (A.z - z1) / (c1 + c2);
    zc = z1 + D * c1;
    yA = A.y;
  } else {
    a2 = n === 11 ? 1.55 : 1.25; D = (n === 11 ? 0.075 : 0.060) * s; zc = z1 + D * Math.cos(a1);
    yA = y1 - (n === 11 ? 0.050 : 0.035) * s;
    A = V(Wn * Math.sin(a2), yA, zc - D * Math.cos(a2));
  }
  return { n, head, tub, x1, y1, z1, Wn, a1, a2, D, zc, yA, A, g };
}

/** x of the point of the sternal border where a cartilage ends: 3 mm inside the bone (the half-width of the sternum there, left frame). */
const sternalEdge = (t, s) => (sternumHalfWidth(t) - 0.003) * s;

/**
 * Costal cartilage of rib n (1-10) as a 3-point path from just behind the bony end A to its other end: the true ribs (1-7) end on the sternum; the
 * false ribs end on the cartilage of the rib above (rib 8 22 % from its sternal end, ribs 9-10 near its rib end), on the curve that cartilage is drawn
 * along, so that the costal arch is one connected structure.
 */
function cartilagePath(ctx, n) {
  const s = ctx.s, A = ribPlan(ctx, n).A, st = sternumFrame(ctx);
  if (n <= 7) {
    const t = RIB_ST[n - 1], c = st.at(t), S = V(sternalEdge(t, s), c.y, c.z + 0.001 * s), mid = A.clone().lerp(S, 0.55);
    mid.y += 0.35 * (S.y - A.y);
    return [A.clone().lerp(S, -0.08), mid, S.clone().lerp(A, -0.02)];
  }
  const above = new THREE.CatmullRomCurve3(cartilagePath(ctx, n - 1), false, "centripetal"); // the same spline the tube of that cartilage follows
  const Q = above.getPointAt(n === 8 ? 0.78 : 0.85);
  return [A.clone().lerp(Q, -0.08), A.clone().lerp(Q, 0.5).add(V(0, 0.004 * s, 0.002 * s)), Q];
}

function buildRib(ctx, def, m) {
  const s = ctx.s, n = def.level, pl = ribPlan(ctx, n), g = pl.g;
  const pts = [];
  const K = 14;
  for (let i = 0; i <= K; i++) {
    const u = i / K, a = pl.a1 + (pl.a2 - pl.a1) * u;
    pts.push(V(pl.Wn * Math.sin(a), pl.y1 + (pl.yA - pl.y1) * u ** 1.25, pl.zc - pl.D * Math.cos(a)));
  }
  // neck: head -> tubercle (a short run behind the transverse process root)
  const neck = [pl.head, pl.head.clone().lerp(pl.tub, 0.55).addScaledVector(g.f, -0.001 * s), pl.tub];
  const path = [...neck.slice(0, 2), ...pts];
  const wide = (0.0058 + 0.0004 * (n > 7 ? 1 : 0)) * s;
  m.tube(path, (t) => {
    const neckPart = smooth(clamp01(1 - t / 0.16)), tip = smooth(clamp01((t - 0.86) / 0.14));
    return { a: wide * (0.9 + 0.7 * tip) + 0.0008 * s * neckPart, b: (0.0022 + 0.0008 * tip + 0.0012 * neckPart) * s, pow: 2.5 };
  }, { hint: Y_, capA: 0.7, capB: 0.5, segs: m.seg(8), density: 150 });
  m.ellipsoid(pl.head.clone().addScaledVector(g.l, 0.001 * s), [0.0060 * s, 0.0058 * s, 0.0060 * s], null, { lat: m.seg(5), lon: m.seg(8) }); // head of the rib
  // costal cartilage (from here on the vertices belong to the sternum: see ribSkin)
  m.color(COLORS.cartilage);
  const nBony = m.pos.length / 3;
  if (n <= 10) {
    const [p0, p1, p2] = cartilagePath(ctx, n);
    m.tube([p0, p1, p2], () => (n <= 7 ? { a: 0.0045 * s, b: 0.0036 * s } : { a: 0.0040 * s, b: 0.0032 * s }), { hint: Y_, segs: m.seg(n <= 7 ? 7 : 6), capA: 0.3, capB: n <= 7 ? 0.5 : 0.4 });
  }
  if (n <= 10) m.skin = { group: "thorax", ids: Array.from({ length: 12 }, (_, i) => `T${i + 1}`), bones: [`T${n}`, BONE_BY_ID.sternum.joint], weights: () => ribWeights(m, nBony, pl) };
  return m;
}

// Ribs 1-10 are skinned between two bones. Their back (head, neck, tubercle, angle) is rigid on the vertebra T_n, which is where the rib
// articulates; their front end and the costal cartilage are carried by the bone of the sternum (T4), because the cartilage ends on the sternum,
// a rigid piece. Rigid on T_n alone, the front ends were left behind by every bend or twist of the thoracic spine (3-7 cm at 30-45 degrees
// of flexion, the cartilage floating off the sternum). The rib between the two is a smooth blend: it bends, as the ribcage does.
const ribBlend = (u) => smooth(clamp01((u - 0.35) / 0.65)); // 0 over the back third of the rib, 1 at the front end

/** Weight of the second bone, the sternum's (0..1), of every vertex of a rib mesh, from its position along the plan-view arc of the rib (left-frame world coordinates). */
function ribWeights(m, nBony, pl) {
  const n = m.pos.length / 3, w = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    if (i >= nBony) { w[i] = 1; continue; }
    const a = Math.atan2(m.pos[3 * i] / pl.Wn, (pl.zc - m.pos[3 * i + 2]) / pl.D);
    w[i] = ribBlend((a - pl.a1) / (pl.a2 - pl.a1));
  }
  return w;
}

// ---------------------------------------------------------------------------------------------------------------------------------------
// Head. Skull in the frame of the occiput-C1 joint (m at 1.75, z forward, y up from that joint): cranium, face, orbits, nasal aperture,
// zygomatic arches, mastoid processes, occipital condyles, upper teeth; mandible in the frame of the jaw joint.
function buildSkull(ctx, def, m) {
  const s = ctx.s, H = ctx.J("head"), E = ctx.J("eye");
  const p = (x, y, z) => H.clone().add(V(x * s, y * s, z * s));
  const r = (x, y, z) => [x * s, y * s, z * s];
  // the face follows the eyes of the body: shifts (m at 1.75) of the eye joint against the model skull's (0.0315, 0.024, 0.088)
  const dx = (E.x - H.x) / s - 0.0315, dy = (E.y - H.y) / s - 0.024, dz = (E.z - H.z) / s - 0.088;
  const pf = (x, y, z) => p(x, y + dy, z + dz);
  const k = (ctx.LM.vertex ? (ctx.LM.vertex.y - H.y) / s : 0.138) / 0.138; // vertex height relative to the model skull
  m.ellipsoid(p(0, 0.0585 * k, 0.004), r(0.0675, 0.0665 * k, 0.088), null, { lat: m.seg(14), lon: m.seg(22), e: 0.9, lower: 0.80 }); // cranial vault with a slightly flatter base
  for (const sd of [1, -1]) m.ellipsoid(p(sd * 0.050, 0.018, -0.012), r(0.022, 0.026, 0.046), null, { lat: m.seg(6), lon: m.seg(10) }); // temporal bones (floor of the temporal fossa)
  m.ellipsoid(p(0, 0.012, -0.050), r(0.040, 0.018, 0.034), null, { lat: m.seg(6), lon: m.seg(10) }); // occipital base
  m.ellipsoid(p(0, 0.018, -0.070), r(0.032, 0.020, 0.015), null, { lat: m.seg(6), lon: m.seg(10) }); // occipital protuberance
  m.ellipsoid(pf(0, 0.016, 0.074), r(0.054, 0.046, 0.032), null, { lat: m.seg(8), lon: m.seg(12) }); // face mass (frontal / nasal)
  m.ellipsoid(pf(0, -0.022, 0.080), r(0.036, 0.023, 0.027), null, { lat: m.seg(8), lon: m.seg(12) }); // maxilla
  m.tube([pf(-0.047, 0.044, 0.091), pf(-0.024, 0.047, 0.101), pf(0, 0.046, 0.103), pf(0.024, 0.047, 0.101), pf(0.047, 0.044, 0.091)], () => ({ a: 0.0052 * s, b: 0.0042 * s }), { hint: Y_, segs: m.seg(7), capA: 0.6, capB: 0.6 }); // brow ridge
  for (const sd of [1, -1]) {
    // orbit: rim (swept ring) with a dark recess behind it, zygomatic bone and arch, mastoid process, ear canal, occipital condyle
    const oc = pf(sd * (0.0325 + dx), 0.027, 0.098), ring = [];
    const nrm = V(sd * 0.18, 0, 1).normalize(), e1 = new THREE.Vector3().crossVectors(Y_, nrm).normalize(), e2 = new THREE.Vector3().crossVectors(nrm, e1);
    // the rim is a rounded square, lying in the face (not a ring standing off it: that read as goggles), a low ridge that is heavy above (the supraorbital
    // margin, which meets the brow) and fine below and next to the nose; the cheek bone joins it laterally
    for (let i = 0; i < 16; i++) {
      const a = (2 * Math.PI * i) / 16, q = oc.clone().addScaledVector(e1, 0.0200 * s * sgnpow(Math.cos(a), 0.78)).addScaledVector(e2, 0.0168 * s * sgnpow(Math.sin(a), 0.78));
      // lie on the face mass (an ellipsoid, see below) instead of in a plane: the face falls away to the side, and a flat ring stood off it
      const fx = (q.x - H.x) / s - dx, fy = (q.y - H.y) / s - dy, t = 1 - (fx / 0.054) ** 2 - ((fy - 0.016) / 0.046) ** 2;
      q.z = H.z + (0.074 + dz + 0.032 * Math.sqrt(Math.max(0.04, t))) * s - 0.0032 * s; // the tube is centred inside the surface: about a third of it shows
      ring.push(q);
    }
    m.tube(ring, (u) => ({ a: (0.0050 + 0.0008 * Math.max(0, Math.sin(2 * Math.PI * u)) ** 2) * s, b: (0.0050 + 0.0014 * Math.max(0, Math.sin(2 * Math.PI * u))) * s, pow: 2 }), { closed: true, hint: nrm, segs: m.seg(7), density: 260 });
    m.color(COLORS.cavity);
    m.ellipsoid(oc.clone().addScaledVector(nrm, -0.005 * s), r(0.0192, 0.0160, 0.0055), basisQ(e1, e2, nrm), { lat: m.seg(6), lon: m.seg(10) });
    m.color(COLORS.bone);
    m.ellipsoid(pf(sd * 0.050, 0.000, 0.080), r(0.0145, 0.0115, 0.0125), null, { lat: m.seg(6), lon: m.seg(9) }); // zygomatic bone
    m.tube([pf(sd * 0.055, 0.003, 0.074), p(sd * 0.0665, 0.006, 0.046), p(sd * 0.0655, 0.008, 0.016), p(sd * 0.0645, 0.009, 0.001)], () => ({ a: 0.0036 * s, b: 0.0026 * s }), { hint: Y_, segs: m.seg(6), capA: 0.6, capB: 0.6 }); // zygomatic arch
    m.ellipsoid(p(sd * 0.052, -0.005, -0.022), r(0.0085, 0.0125, 0.0095), null, { lat: m.seg(5), lon: m.seg(8) }); // mastoid process
    m.color(COLORS.cavity);
    m.ellipsoid(p(sd * 0.0670, 0.008, -0.002), r(0.0025, 0.0045, 0.0045), null, { lat: 4, lon: 6 }); // ear canal
    m.color(COLORS.bone);
    m.ellipsoid(p(sd * 0.0115, -0.003, -0.004), r(0.0085, 0.0060, 0.0150), null, { lat: m.seg(5), lon: m.seg(8) }); // occipital condyle
  }
  m.ellipsoid(pf(0, 0.020, 0.108), r(0.0085, 0.0155, 0.0085), null, { lat: m.seg(5), lon: m.seg(8) }); // nasal bones
  m.color(COLORS.cavity);
  m.ellipsoid(pf(0, -0.007, 0.101), r(0.0105, 0.0165, 0.0075), null, { lat: m.seg(5), lon: m.seg(8) }); // nasal aperture
  m.color(COLORS.bone);
  // upper dental arch: alveolar ridge + 15 teeth (a half ellipse in plan, 55 mm deep, 55 mm wide)
  const archPt = (t, w, z0, dz) => V(w * Math.sin(t), 0, z0 + dz * Math.cos(t));
  const up = []; for (let i = 0; i <= 8; i++) { const q = archPt(-Math.PI / 2 + (Math.PI * i) / 8, 0.0265, 0.054, 0.034); up.push(pf(q.x / s, -0.040, q.z)); }
  m.tube(up, () => ({ a: 0.0072 * s, b: 0.0070 * s }), { hint: Y_, segs: m.seg(7), capA: 0.5, capB: 0.5 });
  m.color(COLORS.tooth);
  for (let i = 0; i <= 14; i++) {
    const t = -Math.PI / 2 + (Math.PI * i) / 14, q = archPt(t, 0.0275, 0.054, 0.037), inc = Math.abs(i - 7) < 3;
    m.ellipsoid(pf(q.x / s, -0.051, q.z), r(inc ? 0.0040 : 0.0052, inc ? 0.0075 : 0.0060, inc ? 0.0028 : 0.0052), frameQ(Y_, V(Math.cos(t), 0, -Math.sin(t))), { lat: 4, lon: 6 });
  }
  return m;
}

// Mandible in the frame of the jaw joint: body (a U in plan, deepest at the chin) from gonion to gonion through the gnathion landmark, rami up to
// the condyles (bicondylar breadth 107 mm), coronoid processes, chin, lower teeth. Everything hangs from the jaw hinge, so it opens with it.
function buildMandible(ctx, def, m) {
  const s = ctx.s, J = ctx.J("jaw"), G = ctx.L("gnathion"), g = G.clone().sub(J); // jaw joint -> chin (down and forward)
  const P = (x, y, z) => J.clone().add(V(x, y, z));
  const gonY = g.y * 0.58, K = 0.0535 * s, up = 0.013 * s; // the lower border passes through the gnathion landmark: the body centre line is half a body height above it
  const left = [P(0.0505 * s, gonY + up, -0.003 * s), P(0.0475 * s, gonY + (g.y - gonY) * 0.45 + up, g.z * 0.30), P(0.0375 * s, gonY + (g.y - gonY) * 0.82 + up, g.z * 0.62), P(0.0185 * s, g.y + up, g.z * 0.90), P(0, g.y + up, g.z)];
  const mir = (q) => V(2 * J.x - q.x, q.y, q.z);
  const path = [...left, ...left.slice(0, -1).reverse().map(mir)];
  m.tube(path, (t) => {
    const mid = 1 - Math.abs(2 * t - 1); // 0 at the angles, 1 at the chin
    return { a: (0.0115 + 0.0045 * mid) * s, b: (0.0058 + 0.0010 * mid) * s, pow: 2.4 };
  }, { hint: Y_, segs: m.seg(8), capA: 0.5, capB: 0.5, density: 150 });
  for (const sd of [1, -1]) {
    const gon = P(sd * 0.0505 * s, gonY, -0.003 * s), con = P(sd * K, 0, 0);
    m.tube([gon, gon.clone().lerp(con, 0.5).add(V(sd * 0.0015 * s, 0, -0.001 * s)), con], (t) => ({ a: (0.0142 - 0.004 * t) * s, b: 0.0030 * s, pow: 2.6 }), { hint: Z_, segs: m.seg(8), capA: 0.4, capB: 0.4 }); // ramus
    m.rod(P(sd * 0.0495 * s, -0.026 * s, 0.014 * s), P(sd * 0.0505 * s, 0.013 * s, 0.015 * s), 0.0085 * s, 0.0030 * s, 0.0020 * s, 0.0026 * s, { hint: Z_, segs: m.seg(6), capB: 0.8 }); // coronoid
    m.ellipsoid(con, [0.0095 * s, 0.0048 * s, 0.0055 * s], null, { lat: m.seg(5), lon: m.seg(8) }); // condyle
  }
  m.ellipsoid(P(0, g.y + 0.007 * s, g.z - 0.003 * s), [0.0125 * s, 0.0085 * s, 0.0065 * s], null, { lat: m.seg(6), lon: m.seg(9) }); // chin
  m.color(COLORS.tooth);
  for (let i = 0; i <= 12; i++) { // lower teeth along an arch 40 mm in front of the angles
    const t = -Math.PI / 2 + (Math.PI * i) / 12, inc = Math.abs(i - 6) < 3, zf = g.z - 0.002 * s, z0 = 0.002 * s;
    m.ellipsoid(P(0.0235 * s * Math.sin(t), g.y + 0.036 * s, z0 + (zf - z0) * (0.5 + 0.5 * Math.cos(t))), [inc ? 0.0034 * s : 0.0050 * s, inc ? 0.0065 * s : 0.0055 * s, inc ? 0.0026 * s : 0.0050 * s], null, { lat: 4, lon: 6 });
  }
  return m;
}

function buildEyeball(ctx, def, m) {
  const s = ctx.s, E = ctx.J("eye"), Pp = ctx.L(`pupil_${ctx.mirror ? "R" : "L"}`), dir = Pp.clone().sub(E);
  m.color(COLORS.eye);
  m.ellipsoid(E, [0.0118 * s, 0.0118 * s, 0.0118 * s], null, { lat: m.seg(7), lon: m.seg(10) });
  m.color(COLORS.iris);
  const n = dir.clone().normalize(), e1 = new THREE.Vector3().crossVectors(Y_, n).normalize(), e2 = new THREE.Vector3().crossVectors(n, e1);
  m.ellipsoid(Pp.clone().addScaledVector(n, -0.0012 * s), [0.0052 * s, 0.0052 * s, 0.0016 * s], basisQ(e1, e2, n), { lat: 4, lon: 8 }); // iris / pupil: dark disc on the cornea
  return m;
}

// ---------------------------------------------------------------------------------------------------------------------------------------
// Limbs. A limb frame: d along the bone (proximal -> distal), lat = lateral (+X for the left side), f = forward (d x lat; +Z for a hanging arm).
function limbFrame(a, b) {
  const L = a.distanceTo(b), d = b.clone().sub(a).divideScalar(L);
  let lat = X_.clone().addScaledVector(d, -d.x);
  lat = lat.lengthSq() > 1e-8 ? lat.normalize() : Z_.clone().addScaledVector(d, -d.z).normalize(); // a bone lying along X: use Z
  const f = d.clone().cross(lat);
  return { a, b, L, d, lat, f, at: (t, lo = 0, fo = 0) => a.clone().addScaledVector(d, t * L).addScaledVector(lat, lo).addScaledVector(f, fo) };
}
/** Piecewise-linear table [[t, v], ...] -> function(t). */
const interp = (tb) => (t) => {
  if (t <= tb[0][0]) return tb[0][1];
  for (let i = 1; i < tb.length; i++) if (t <= tb[i][0]) { const [t0, v0] = tb[i - 1], [t1, v1] = tb[i]; return v0 + ((v1 - v0) * (t - t0)) / (t1 - t0); }
  return tb[tb.length - 1][1];
};
const blob = (m, c, r, q = null, o = {}) => m.ellipsoid(c, r, q, { lat: o.lat ?? m.seg(6), lon: o.lon ?? m.seg(9), e: o.e, lower: o.lower });

// Clavicle: S-shaped (convex forward in the medial two thirds, concave forward in the lateral third), round and thick medially, flat
// and wide laterally; the sternal end is a bulb. From the sternoclavicular joint to just inside the acromion landmark.
function buildClavicle(ctx, def, m) {
  const s = ctx.s, a = ctx.J("clavicle"), b = ctx.L("acromion_L").clone().add(V(-0.010 * s, -0.004 * s, 0));
  const F = limbFrame(a, b), k = F.L / 0.150; // the S-curve scales with the length of the bone (0.150 m at 1.75 m is about 150 mm / 1.0)
  const bow = [[0, 0], [0.2, 0.005], [0.4, 0.0105], [0.6, 0.0075], [0.8, -0.003], [1, -0.0095]];
  const pts = bow.map(([t, z]) => a.clone().lerp(b, t).addScaledVector(Z_, z * s * Math.min(1.4, k)).addScaledVector(Y_, 0.004 * s * Math.sin(Math.PI * t)));
  const wa = interp([[0, 0.0105], [0.15, 0.0080], [0.4, 0.0072], [0.65, 0.0064], [0.85, 0.0046], [1, 0.0036]]), wb = interp([[0, 0.0105], [0.15, 0.0082], [0.4, 0.0076], [0.65, 0.0086], [0.85, 0.0118], [1, 0.0140]]);
  m.tube(pts, (t) => ({ a: wa(t) * s, b: wb(t) * s, pow: 2.3, lobes: [3, 0.07, 0.4] }), { hint: Y_, segs: m.seg(10), capA: 0.45, capB: 0.3, density: 140 });
  blob(m, a.clone().addScaledVector(F.d, 0.002 * s), [0.0098 * s, 0.0098 * s, 0.0098 * s]);
  return m;
}

// Scapula: a triangular curved plate (vertebral border vertical, 150 mm; lateral angle at the glenoid; inferior angle at the landmark), the spine
// of the scapula running out to the acromion, coracoid process, glenoid. The plate is a thin cup, thick at the borders.
function buildScapula(ctx, def, m) {
  const s = ctx.s, G = ctx.J("shoulder"), Ii = ctx.L("scapula_inferior_L").clone().add(V(0, 0, 0.020 * s));
  const gdir = V(0.80, 0.10, 0.59).normalize();
  const Gl = G.clone().addScaledVector(gdir, -0.021 * s);
  const S0 = Ii.clone().add(V(-0.006 * s, 0.150 * s, 0.006 * s));
  const Lc = Gl.clone().add(V(0, -0.004 * s, 0));
  // plane normal (outward = backward) from the three corners; bend toward the ribs
  const n = new THREE.Vector3().crossVectors(S0.clone().sub(Ii), Lc.clone().sub(Ii)).normalize();
  if (n.z > 0) n.negate(); // the outward side of the plate faces backward
  const S = (u, v) => Ii.clone().addScaledVector(S0.clone().sub(Ii), u).addScaledVector(Lc.clone().sub(Ii), v).addScaledVector(n, 0.012 * s * 27 * Math.max(0, u * v * (1 - u - v)) * -0.55);
  const perim = [];
  // rounded triangle: vertices (u, v) = (0, 0) = inferior angle, (1, 0) = superior angle, (0, 1) = glenoid corner
  const corners = [[0, 0], [1, 0], [0, 1]];
  const cut = 0.07;
  const loop = [];
  for (let i = 0; i < 3; i++) {
    const c = corners[i], p = corners[(i + 2) % 3], q = corners[(i + 1) % 3];
    loop.push([c[0] + (p[0] - c[0]) * cut, c[1] + (p[1] - c[1]) * cut], [c[0], c[1]], [c[0] + (q[0] - c[0]) * cut, c[1] + (q[1] - c[1]) * cut]);
  }
  const cr = new THREE.CatmullRomCurve3(loop.map(([u, v]) => V(u, v, 0)), true, "centripetal");
  for (let i = 0; i < m.seg(30); i++) { const pt = cr.getPoint(i / m.seg(30)); perim.push([pt.x, pt.y]); }
  m.plate(S, perim, [0.33, 0.33], () => 0.011 * s, { rings: m.seg(5), mid: 0.30 });
  // axillary (lateral) border thickening and the spine of the scapula
  m.rod(Ii.clone().addScaledVector(n, 0.002 * s), Lc.clone().addScaledVector(n, 0.001 * s), 0.0045 * s, 0.0040 * s, 0.0060 * s, 0.0055 * s, { hint: n, segs: m.seg(7) });
  const sp0 = Ii.clone().lerp(S0, 0.72).addScaledVector(n, 0.003 * s);
  const acr = ctx.L("acromion_L").clone().add(V(-0.006 * s, -0.002 * s, 0));
  const mid = sp0.clone().lerp(Lc, 0.5).addScaledVector(n, 0.011 * s).add(V(0, 0.008 * s, 0));
  const rise = Lc.clone().addScaledVector(n, 0.006 * s).add(V(0.010 * s, 0.020 * s, -0.004 * s));
  m.tube([sp0, mid, rise, acr], (t) => ({ a: (0.0052 + 0.0030 * t) * s, b: (0.0050 - 0.0014 * t) * s, pow: 2.2, lobes: [3, 0.18, 0] }), { hint: n, segs: m.seg(8), capA: 0.4, capB: 0.4, density: 150 });
  const adir = acr.clone().sub(rise).normalize();
  blob(m, acr.clone().addScaledVector(adir, -0.006 * s), [0.0125 * s, 0.0050 * s, 0.0105 * s], frameQ(n, adir)); // acromion: flat shelf over the joint
  // coracoid process: from the upper glenoid forward and out
  const c0 = Lc.clone().add(V(0.002 * s, 0.008 * s, 0.003 * s)), c1 = c0.clone().add(V(0.004 * s, 0.012 * s, 0.020 * s)), c2 = c1.clone().add(V(0.013 * s, -0.002 * s, 0.014 * s));
  m.tube([c0, c1, c2], (t) => ({ a: (0.0072 - 0.0030 * t) * s, b: (0.0056 - 0.0020 * t) * s }), { hint: Y_, segs: m.seg(7), capA: 0.4, capB: 0.6 });
  // glenoid: pear-shaped shallow socket facing lateral / forward
  blob(m, Gl, [0.0105 * s, 0.0150 * s, 0.0055 * s], frameQ(Y_, gdir), {});
  m.rod(Gl.clone().addScaledVector(gdir, -0.012 * s), Gl, 0.0090 * s, 0.0080 * s, 0.0105 * s, 0.0105 * s, { hint: Y_, segs: m.seg(8) });
  return m;
}

// Humerus: head (sphere 0.073 L radius) on a short neck at 135 deg, greater and lesser tuberosities, round shaft turning flat and wide
// toward the elbow, deltoid tuberosity, spool-shaped condyle (trochlea + capitulum) with the two epicondyles. L = shoulder-elbow distance.
function buildHumerus(ctx, def, m) {
  const G = ctx.J("shoulder"), E = ctx.J("elbow"), F = limbFrame(G, E), L = F.L, s = ctx.s;
  const r = (v) => v * L;
  blob(m, G, [r(0.073), r(0.073), r(0.073)], null, { lat: m.seg(9), lon: m.seg(14) });
  const neckEnd = F.at(0.10, r(0.062), r(0.004));
  m.rod(G.clone().addScaledVector(F.lat, r(0.012)), neckEnd, r(0.044), r(0.044), r(0.036), r(0.036), { segs: m.seg(9) });
  blob(m, F.at(0.045, r(0.080), r(0.0)), [r(0.036), r(0.052), r(0.040)], null); // greater tuberosity
  blob(m, F.at(0.045, r(0.028), r(0.060)), [r(0.027), r(0.040), r(0.026)], null); // lesser tuberosity
  const off = (t) => r(0.060) * (1 - t) ** 1.4;
  const pts = [0.10, 0.25, 0.45, 0.65, 0.82, 0.955].map((t) => F.at(t, off(t), r(0.006) * Math.sin(Math.PI * t)));
  const sa = interp([[0, 0.036], [0.3, 0.033], [0.6, 0.032], [0.85, 0.027], [1, 0.024]]), sb = interp([[0, 0.038], [0.3, 0.033], [0.6, 0.033], [0.85, 0.040], [1, 0.050]]);
  m.tube(pts, (t) => ({ a: r(sa(t)), b: r(sb(t)), pow: 2.2, lobes: [3, 0.06 * t, 0] }), { hint: F.f, segs: m.seg(10), capA: 0.2, capB: 0.2, density: 100 });
  blob(m, F.at(0.42, r(0.040), r(0.004)), [r(0.016), r(0.060), r(0.018)], null); // deltoid tuberosity
  const lower = F.at(0.945, 0, 0);
  blob(m, lower.clone().addScaledVector(F.d, r(0.026)).addScaledVector(F.f, r(0.003)), [r(0.066), r(0.040), r(0.040)], null, { lat: m.seg(7), lon: m.seg(12) }); // trochlea / capitulum spool
  blob(m, E.clone().addScaledVector(F.lat, -r(0.104)).addScaledVector(F.d, -r(0.030)), [r(0.025), r(0.034), r(0.032)], null); // medial epicondyle
  blob(m, E.clone().addScaledVector(F.lat, r(0.080)).addScaledVector(F.d, -r(0.026)), [r(0.020), r(0.030), r(0.026)], null); // lateral epicondyle
  return m;
}

// Ulna (fixed to the elbow joint): olecranon behind and above the hinge, coronoid in front, triangular shaft tapering to a small head with
// the styloid process; it is on the back (posterior) side of the forearm in mid-position. L = elbow-wrist distance.
function buildUlna(ctx, def, m) {
  const E = ctx.J("elbow"), W = ctx.J("wrist"), F = limbFrame(E, W), L = F.L, s = ctx.s;
  const r = (v) => v * L;
  blob(m, E.clone().addScaledVector(F.d, -r(0.030)).addScaledVector(F.f, -r(0.066)), [r(0.052), r(0.086), r(0.046)], null, { lat: m.seg(7), lon: m.seg(10) }); // olecranon
  blob(m, E.clone().addScaledVector(F.d, r(0.040)).addScaledVector(F.f, r(0.026)), [r(0.040), r(0.040), r(0.040)], null); // coronoid
  blob(m, E.clone().addScaledVector(F.d, r(0.020)).addScaledVector(F.f, -r(0.020)).addScaledVector(F.lat, r(0.012)), [r(0.040), r(0.062), r(0.052)], null); // body of the proximal end
  const pts = [0.07, 0.25, 0.5, 0.75, 0.96].map((t) => F.at(t, -r(0.006) * t, -r(0.034)));
  const sa = interp([[0, 0.044], [0.3, 0.030], [0.6, 0.022], [1, 0.017]]);
  m.tube(pts, (t) => ({ a: r(sa(t)), b: r(sa(t)) * 0.9, pow: 2.2, lobes: [3, 0.14, 1.0] }), { hint: F.f, segs: m.seg(9), capA: 0.3, capB: 0.3, density: 90 });
  const head = F.at(0.975, -r(0.006), -r(0.044));
  blob(m, head, [r(0.034), r(0.030), r(0.034)], null);
  m.rod(head.clone().addScaledVector(F.lat, -r(0.005)), head.clone().addScaledVector(F.d, r(0.030)).addScaledVector(F.lat, -r(0.012)), r(0.013), r(0.013), r(0.007), r(0.007), { segs: m.seg(6), capB: 0.8 }); // styloid
  return m;
}

// Radius (moves with the forearm roll): disc-shaped head lateral to the hinge, bowed shaft, wide distal end with the styloid; in mid-position
// it lies on the thumb (front) side of the ulna. The forearm roll turns about the vertical line through the wrist centre (rig.js: the forearm joint is
// on it), which is up to 14 cm from the elbow when the arm hangs tilted away from the body, so a radius rigid on the forearm joint would swing its head
// off the humerus. It is skinned between the elbow bone (the head, which stays on the humerus as the radial head does, turning in place) and the
// forearm bone (the distal end, which turns with the hand): the shaft in between is a smooth blend of the two (full weight at 88 % of the way down),
// so it bows across the ulna in pronation, as it does in the body, instead of kinking.
function buildRadius(ctx, def, m) {
  const E = ctx.J("elbow"), W = ctx.J("wrist"), F = limbFrame(E, W), L = F.L, s = ctx.s;
  const r = (v) => v * L;
  const head = F.at(0.018, r(0.072), r(0.012));
  const side = def.side;
  m.skin = {
    group: `forearm_${side}`, ids: [`elbow_${side}`, `forearm_${side}`], bones: [`elbow_${side}`, `forearm_${side}`],
    weights: () => { // 0 = elbow, 1 = forearm joint, by the position along the forearm
      const n = m.pos.length / 3, w = new Float32Array(n), v = V();
      for (let i = 0; i < n; i++) w[i] = smooth(clamp01((v.set(m.pos[3 * i], m.pos[3 * i + 1], m.pos[3 * i + 2]).sub(E).dot(F.d) / L - 0.03) / 0.85));
      return w;
    },
  };
  blob(m, head, [r(0.043), r(0.020), r(0.043)], frameQ(F.d, F.f), { lat: m.seg(6), lon: m.seg(10) });
  const dist = F.at(0.965, r(0.002), r(0.040));
  const pts = [head.clone().addScaledVector(F.d, r(0.030)), F.at(0.14, r(0.060), r(0.014)), F.at(0.35, r(0.050), r(0.026)), F.at(0.62, r(0.022), r(0.036)), F.at(0.86, r(0.006), r(0.040)), dist.clone().addScaledVector(F.d, -r(0.020))];
  const sa = interp([[0, 0.020], [0.15, 0.022], [0.45, 0.027], [0.8, 0.030], [1, 0.040]]), sb = interp([[0, 0.020], [0.15, 0.022], [0.45, 0.022], [0.8, 0.034], [1, 0.050]]);
  m.tube(pts, (t) => ({ a: r(sa(t)), b: r(sb(t)), pow: 2.2, lobes: [3, 0.10, 2.2] }), { hint: F.lat, segs: m.seg(9), capA: 0.3, capB: 0.2, density: 90 });
  blob(m, dist.clone().addScaledVector(F.d, -r(0.002)), [r(0.052), r(0.038), r(0.066)], null, { lat: m.seg(7), lon: m.seg(10) }); // distal end (broad radio-ulnar)
  m.rod(dist.clone().addScaledVector(F.f, r(0.036)).addScaledVector(F.d, -r(0.005)), dist.clone().addScaledVector(F.f, r(0.040)).addScaledVector(F.d, r(0.032)).addScaledVector(F.lat, r(0.006)), r(0.015), r(0.015), r(0.007), r(0.007), { segs: m.seg(6), capB: 0.8 }); // styloid
  return m;
}

// Hand. dorsal = lateral (+X) for the left hand, palmar = medial; fingers hang along -Y.
function boneShaft(m, a, b, o) {
  // generic long bone between a and b: shaft with flared base and head; r* are ratios of the length; dorsal axis = `dorsal`
  const L = a.distanceTo(b), d = b.clone().sub(a).normalize(), r = (v) => v * L;
  const lo = o.base ?? 0.10, hi = o.head ?? 0.10;
  const A = a.clone().addScaledVector(d, r(lo * 0.5)), B = b.clone().addScaledVector(d, -r(hi * 0.5));
  const bow = o.bow ?? 0;
  const mid = A.clone().lerp(B, 0.5).addScaledVector(o.dorsal, bow * L);
  m.tube([A, mid, B], (t) => {
    const fb = 1 + (o.flareB ?? 0.8) * smooth(clamp01(1 - t / (o.flareLen ?? 0.2))), fh = 1 + (o.flareH ?? 0.45) * smooth(clamp01((t - 0.8) / 0.2));
    const k = Math.max(fb, fh);
    return { a: r(o.ra) * (1 + 0.4 * (k - 1)), b: r(o.rb) * k, pow: 2.2 };
  }, { hint: o.dorsal, segs: m.seg(7), capA: 0.3, capB: 0.3, n: 8 });
  if (o.headR) blob(m, b.clone().addScaledVector(d, -r(0.04)), [r(o.headR * (o.headFlat ?? 0.9)), r(o.headR), r(o.headR)], frameQ(d, Z_), { lat: m.seg(5), lon: m.seg(8) });
  return m;
}

function buildMetacarpal(ctx, def, m) {
  const s = ctx.s, num = +def.id.split("_")[1];
  const W = ctx.J("wrist");
  const dorsal = X_;
  if (num === 1) {
    const a = ctx.J("thumb_cmc"), b = ctx.J("thumb_mcp");
    boneShaft(m, a, b, { ra: 0.085, rb: 0.095, headR: 0.125, bow: 0.02, dorsal, flareB: 0.7, base: 0.12 });
    blob(m, a.clone().addScaledVector(b.clone().sub(a).normalize(), -0.006 * s), [0.0060 * s, 0.0095 * s, 0.0100 * s], null); // trapezium
    return m;
  }
  const mcp = ctx.J(["", "", "index", "middle", "ring", "little"][num] + "_mcp");
  const base = W.clone().lerp(mcp, 0.30);
  boneShaft(m, base, mcp, { ra: 0.050, rb: 0.058, headR: 0.108, bow: 0.04, dorsal, flareB: 0.85, base: 0.10 });
  if (num === 3) { // the eight carpal bones ride with the wrist: they are drawn as part of the middle metacarpal's mesh
    const Lc = 0.30 * W.distanceTo(mcp), p = (z, t, x = 0) => W.clone().add(V(x * s, -t * Lc, z * s));
    const row = (t, items) => items.forEach(([z, x, rr]) => blob(m, p(z, t, x), [0.0078 * s * rr, 0.0072 * s * rr, 0.0085 * s * rr], null, { lat: m.seg(5), lon: m.seg(8) }));
    row(0.18, [[0.016, 0, 1.25], [0.003, 0.001, 1.15], [-0.009, 0, 1.15], [-0.017, -0.007, 0.85]]); // scaphoid, lunate, triquetrum, pisiform
    row(0.72, [[0.023, 0, 1.1], [0.011, 0, 0.95], [-0.001, 0, 1.3], [-0.014, -0.001, 1.2]]); // trapezium, trapezoid, capitate, hamate
  }
  return m;
}

function buildPhalanx(ctx, def, m) {
  const s = ctx.s, a = ctx.end(def.from), dir0 = ctx.end(def.to).clone().sub(a);
  const distal = def.id.includes("_3_") || def.id.includes("thumb_2");
  let b = ctx.end(def.to);
  if (def.to.startsWith("lm:")) b = b.clone().addScaledVector(dir0.clone().normalize(), -0.004 * s); // the landmark is the pulp end, the bone stops short of it
  const proximal = /_1_/.test(def.id);
  boneShaft(m, a, b, { ra: distal ? 0.070 : proximal ? 0.072 : 0.070, rb: distal ? 0.080 : proximal ? 0.088 : 0.084, headR: distal ? 0 : 0.100, bow: 0.015, dorsal: X_, flareB: 0.55, base: 0.12, head: distal ? 0.05 : 0.12, flareH: 0.35 });
  if (distal) blob(m, b.clone().addScaledVector(dir0.clone().normalize(), -0.002 * s), [0.0030 * s, 0.0050 * s, 0.0046 * s], frameQ(dir0, Z_), { lat: m.seg(5), lon: m.seg(8) }); // tuft
  return m;
}

// Femur. L = hip-knee distance; ratios of L (0.43 m): head radius 0.055, neck 0.123 lateral + 0.086 down, shaft radius 0.030-0.045, bow 0.026,
// condyles 0.054 apart. The shaft starts lateral of the hip-knee line (about 0.12 L) and comes back to it at the knee.
function buildFemur(ctx, def, m) {
  const H = ctx.J("hip"), K = ctx.J("knee"), F = limbFrame(H, K), L = F.L, s = ctx.s;
  const r = (v) => v * L;
  blob(m, H, [r(0.055), r(0.055), r(0.055)], null, { lat: m.seg(8), lon: m.seg(12) });
  const N = H.clone().addScaledVector(F.lat, r(0.112)).addScaledVector(F.d, r(0.088)).addScaledVector(F.f, r(0.012));
  m.rod(H, N, r(0.033), r(0.031), r(0.040), r(0.036), { segs: m.seg(9), capA: 0.1 });
  blob(m, H.clone().addScaledVector(F.lat, r(0.132)).addScaledVector(F.d, r(0.075)).addScaledVector(F.f, -r(0.020)), [r(0.032), r(0.050), r(0.036)], null, { lat: m.seg(7), lon: m.seg(10) }); // greater trochanter
  blob(m, H.clone().addScaledVector(F.lat, r(0.082)).addScaledVector(F.d, r(0.205)).addScaledVector(F.f, -r(0.032)), [r(0.014), r(0.022), r(0.016)], null); // lesser trochanter
  const prof = [[0.08, 0.130, -0.004], [0.30, 0.092, 0.012], [0.50, 0.064, 0.026], [0.72, 0.034, 0.021], [0.90, 0.014, 0.009], [0.95, 0.004, 0.002]];
  const pts = prof.map(([t, lo, fo]) => F.at(t, r(lo), r(fo)));
  const sa = interp([[0.12, 0.037], [0.3, 0.033], [0.55, 0.030], [0.8, 0.035], [0.95, 0.044]]), sb = interp([[0.12, 0.040], [0.3, 0.035], [0.55, 0.031], [0.8, 0.038], [0.95, 0.054]]);
  m.tube(pts, (u) => { const t = 0.12 + 0.83 * u; return { a: r(sa(t)), b: r(sb(t)), pow: 2.2, lobes: [2, 0.05, 0] }; }, { hint: F.f, segs: m.seg(10), capA: 0.9, capB: 0.2, density: 90 }); // the top end is buried in the trochanter
  for (const sd of [1, -1]) { // medial / lateral condyle (the medial one is a little larger); lateral = +lat
    blob(m, K.clone().addScaledVector(F.lat, sd * r(0.056)).addScaledVector(F.d, -r(0.012)).addScaledVector(F.f, -r(0.030)), [r(sd > 0 ? 0.042 : 0.046), r(0.054), r(0.066)], null, { lat: m.seg(8), lon: m.seg(11) });
  }
  blob(m, K.clone().addScaledVector(F.d, -r(0.040)).addScaledVector(F.f, r(0.036)), [r(0.062), r(0.052), r(0.034)], null); // patellar surface
  blob(m, K.clone().addScaledVector(F.lat, r(0.094)).addScaledVector(F.d, -r(0.012)), [r(0.014), r(0.018), r(0.018)], null); // lateral epicondyle
  blob(m, K.clone().addScaledVector(F.lat, -r(0.098)).addScaledVector(F.d, -r(0.022)), [r(0.016), r(0.022), r(0.018)], null); // adductor tubercle / medial epicondyle
  return m;
}

function buildPatella(ctx, def, m) {
  const s = ctx.s, c = ctx.L("patella_L").clone().addScaledVector(Z_, -0.019 * s);
  blob(m, c, [0.0225 * s, 0.0245 * s, 0.0100 * s], null, { lat: m.seg(7), lon: m.seg(10) });
  blob(m, c.clone().add(V(0, -0.016 * s, -0.002 * s)), [0.0100 * s, 0.0100 * s, 0.0070 * s], null); // apex
  return m;
}

// Tibia: plateau (two condyles) just below the joint line, tuberosity, triangular shaft with the sharp edge in front, flared lower end
// with the medial malleolus. L = knee-ankle distance. Fibula: head behind and below the lateral condyle, thin slightly bowed shaft,
// lateral malleolus reaching lower than the medial one.
function buildTibia(ctx, def, m) {
  const K = ctx.J("knee"), A = ctx.J("ankle"), F = limbFrame(K, A), L = F.L, s = ctx.s;
  const r = (v) => v * L;
  for (const sd of [1, -1]) blob(m, K.clone().addScaledVector(F.lat, sd * r(0.048)).addScaledVector(F.d, r(0.030)).addScaledVector(F.f, -r(0.002)), [r(sd > 0 ? 0.046 : 0.050), r(0.026), r(0.060)], null, { lat: m.seg(7), lon: m.seg(11) }); // condyles with the plateau on top
  blob(m, K.clone().addScaledVector(F.d, r(0.014)).addScaledVector(F.f, r(0.002)), [r(0.014), r(0.020), r(0.026)], null); // intercondylar eminence
  blob(m, K.clone().addScaledVector(F.d, r(0.118)).addScaledVector(F.f, r(0.052)), [r(0.020), r(0.034), r(0.017)], null); // tuberosity
  const pts = [0.045, 0.20, 0.42, 0.66, 0.85, 0.975].map((t) => F.at(t, r(0.002) * t, r(0.006) + r(0.004) * Math.sin(Math.PI * t)));
  const sa = interp([[0, 0.060], [0.1, 0.050], [0.4, 0.038], [0.7, 0.034], [1, 0.044]]), sb = interp([[0, 0.092], [0.1, 0.066], [0.4, 0.034], [0.7, 0.032], [1, 0.062]]);
  m.tube(pts, (u) => { const t = 0.045 + 0.93 * u; return { a: r(sa(u)), b: r(sb(u)), pow: 2.2, lobes: [3, 0.17 * smooth(clamp01(u * 3)) * (1 - 0.8 * smooth(clamp01((u - 0.85) / 0.15))), 0] }; }, { hint: F.f, segs: m.seg(10), capA: 0.12, capB: 0.2, density: 90 });
  blob(m, A.clone().addScaledVector(F.d, -r(0.002)), [r(0.076), r(0.026), r(0.054)], null); // distal articular end (plafond)
  blob(m, A.clone().addScaledVector(F.lat, -r(0.070)).addScaledVector(F.d, r(0.012)).addScaledVector(F.f, -r(0.004)), [r(0.022), r(0.042), r(0.034)], null, { lat: m.seg(6), lon: m.seg(9) }); // medial malleolus
  return m;
}

function buildFibula(ctx, def, m) {
  const K = ctx.J("knee"), A = ctx.J("ankle"), F = limbFrame(K, A), L = F.L, s = ctx.s;
  const r = (v) => v * L;
  const head = K.clone().addScaledVector(F.lat, r(0.074)).addScaledVector(F.d, r(0.070)).addScaledVector(F.f, -r(0.034));
  const mal = A.clone().addScaledVector(F.lat, r(0.078)).addScaledVector(F.d, r(0.020)).addScaledVector(F.f, -r(0.014));
  blob(m, head, [r(0.030), r(0.030), r(0.028)], null);
  const pts = [head.clone().addScaledVector(F.d, r(0.020)), F.at(0.25, r(0.078), -r(0.040)), F.at(0.55, r(0.079), -r(0.040)), F.at(0.82, r(0.078), -r(0.030)), mal.clone().addScaledVector(F.d, -r(0.040))];
  m.tube(pts, (t) => ({ a: r(0.015 + 0.008 * Math.max(0, 1 - 4 * t) + 0.012 * Math.max(0, t - 0.8) * 5 * 0.4), b: r(0.015 + 0.004 * t), pow: 2.2, lobes: [3, 0.18, 1.0] }), { hint: F.f, segs: m.seg(8), capA: 0.3, capB: 0.3, density: 90 });
  blob(m, mal, [r(0.017), r(0.038), r(0.026)], null, { lat: m.seg(6), lon: m.seg(9) }); // lateral malleolus
  return m;
}

// Foot. Calcaneus (heel bone) from the heel point to under the ankle; "metatarsus" = talus, navicular, cuboid, three cuneiforms and the five
// metatarsals (shorter and higher at the base, the heads along the ball of the foot); toes = 14 phalanges (hallux 2, the others 3).
function buildCalcaneus(ctx, def, m) {
  // the heel of a fitted body has its pternion (heel_L, the most posterior point) about 45 mm above the floor and the sole point at the floor
  // (heel_sole_L): the bone sits in the heel pad, its tuberosity 26 mm above the sole and just in front of the pternion
  const s = ctx.s, A = ctx.J("ankle"), Hh = ctx.L("heel_L"), Hs = ctx.LM.heel_sole_L;
  const floor = Hs ? (ctx.mirror ? ctx.L("heel_sole_L") : Hs).y : Hh.y - 0.045 * s;
  const P0 = V(Hh.x, floor + 0.026 * s, Hh.z + 0.014 * s), P1 = A.clone().add(V(0, -0.034 * s, -0.008 * s)), P2 = A.clone().add(V(0.002 * s, -0.039 * s, 0.030 * s));
  m.tube([P0, P1, P2], (t) => ({ a: (0.0195 - 0.0070 * t) * s, b: (0.0160 - 0.0030 * t) * s, pow: 2.3 }), { hint: Y_, segs: m.seg(9), capA: 0.5, capB: 0.5, density: 150 });
  blob(m, A.clone().add(V(-0.015 * s, -0.030 * s, 0.004 * s)), [0.0075 * s, 0.0070 * s, 0.0130 * s], null); // sustentaculum tali
  blob(m, P0.clone().add(V(0, -0.004 * s, 0.002 * s)), [0.0130 * s, 0.0150 * s, 0.0110 * s], null, { lat: m.seg(6), lon: m.seg(9) }); // heel tuberosity
  return m;
}

function buildTarsalsMetatarsals(ctx, def, m) {
  const s = ctx.s, A = ctx.J("ankle"), M = ctx.J("mtp"), T = ctx.L("toe_tip_L");
  const p = (x, y, z) => A.clone().add(V(x * s, y * s, z * s));
  blob(m, p(0, -0.017, 0.012), [0.0185 * s, 0.0135 * s, 0.0300 * s], null, { lat: m.seg(7), lon: m.seg(10) }); // talus
  blob(m, p(-0.013, -0.031, 0.050), [0.0105 * s, 0.0150 * s, 0.0090 * s], null); // navicular
  blob(m, p(0.020, -0.034, 0.052), [0.0140 * s, 0.0135 * s, 0.0130 * s], null); // cuboid
  [[-0.021, 0.073, 0.0105], [-0.006, 0.077, 0.0090], [0.008, 0.073, 0.0095]].forEach(([x, z, rr]) => blob(m, p(x, -0.034, z), [rr * s, 0.0120 * s, 0.0110 * s], null)); // cuneiforms
  const headX = [-0.027, -0.0135, 0.0, 0.0135, 0.0265], headDz = [0, 0.002, 0, -0.003, -0.008];
  const baseX = [-0.020, -0.010, 0.0, 0.011, 0.027], baseZ = [0.082, 0.090, 0.088, 0.086, 0.078], baseY = [-0.030, -0.025, -0.027, -0.031, -0.040];
  for (let i = 0; i < 5; i++) {
    const head = V(M.x + (headX[i] - 0.0) * s, M.y, M.z + headDz[i] * s), base = p(baseX[i], baseY[i], baseZ[i]);
    const big = i === 0;
    boneShaft(m, base, head, { ra: big ? 0.100 : 0.075, rb: big ? 0.115 : 0.085, headR: big ? 0.150 : 0.115, headFlat: 0.9, bow: -0.018, dorsal: Y_, flareB: 0.9, base: 0.18, flareLen: 0.25, head: 0.14, flareH: 0.5 });
    if (i === 4) blob(m, base.clone().add(V(0.008 * s, 0.003 * s, -0.004 * s)), [0.0075 * s, 0.0070 * s, 0.0085 * s], null); // tuberosity of the fifth metatarsal
  }
  return m;
}

function buildToes(ctx, def, m) {
  const s = ctx.s, M = ctx.J("mtp"), T = ctx.L("toe_tip_L");
  const Lt = T.z - M.z, step = [0, 0.0140, 0.0280, 0.0415, 0.0555], lenF = [1, 0.97, 0.84, 0.72, 0.60], seg = [[0.55, 0.45], [0.46, 0.30, 0.24], [0.46, 0.30, 0.24], [0.46, 0.30, 0.24], [0.46, 0.30, 0.24]];
  for (let i = 0; i < 5; i++) {
    const x = T.x + step[i] * s, z0 = M.z + (i === 0 ? 0 : (i * 0.002) * -1) * s, tipZ = M.z + (Lt - 0.004 * s) * lenF[i];
    const y0 = M.y, y1 = T.y + 0.001 * s;
    const total = tipZ - z0;
    let z = z0;
    seg[i].forEach((fr, k) => {
      const zz = z + total * fr, last = k === seg[i].length - 1;
      const a = V(x, y0 + (y1 - y0) * ((z - z0) / total), z), b = V(x, y0 + (y1 - y0) * ((zz - z0) / total), zz);
      boneShaft(m, a, b, { ra: i === 0 ? 0.100 : 0.095, rb: i === 0 ? 0.115 : 0.105, headR: last ? 0 : 0.115, bow: 0.01, dorsal: Y_, flareB: 0.5, base: 0.14, head: last ? 0.04 : 0.12, flareH: 0.3 });
      if (last) blob(m, b.clone().add(V(0, 0, -0.001 * s)), [(i === 0 ? 0.0075 : 0.0045) * s, 0.0036 * s, (i === 0 ? 0.0055 : 0.0040) * s], null, { lat: m.seg(5), lon: m.seg(8) });
      z = zz;
    });
  }
  return m;
}

function buildBone(ctx, def) {
  const m = new Mesher(ctx.q);
  const id = def.id;
  if (def.kind === "vertebra") return buildVertebra(ctx, def, m);
  if (id === "sacrum") return buildSacrum(ctx, def, m);
  if (id.startsWith("innominate")) return buildInnominate(ctx, def, m);
  if (id === "sternum") return buildSternum(ctx, def, m);
  if (def.kind === "rib") return buildRib(ctx, def, m);
  if (id === "skull") return buildSkull(ctx, def, m);
  if (id === "mandible") return buildMandible(ctx, def, m);
  if (def.kind === "eyeball") return buildEyeball(ctx, def, m);
  if (id.startsWith("clavicle_bone")) return buildClavicle(ctx, def, m);
  if (id.startsWith("scapula")) return buildScapula(ctx, def, m);
  if (id.startsWith("humerus")) return buildHumerus(ctx, def, m);
  if (id.startsWith("ulna")) return buildUlna(ctx, def, m);
  if (id.startsWith("radius")) return buildRadius(ctx, def, m);
  if (id.startsWith("metacarpal")) return buildMetacarpal(ctx, def, m);
  if (def.kind === "phalanx" && def.digit) return buildPhalanx(ctx, def, m);
  if (id.startsWith("femur")) return buildFemur(ctx, def, m);
  if (id.startsWith("patella")) return buildPatella(ctx, def, m);
  if (id.startsWith("tibia")) return buildTibia(ctx, def, m);
  if (id.startsWith("fibula")) return buildFibula(ctx, def, m);
  if (id.startsWith("calcaneus")) return buildCalcaneus(ctx, def, m);
  if (id.startsWith("metatarsus")) return buildTarsalsMetatarsals(ctx, def, m);
  if (id.startsWith("toes")) return buildToes(ctx, def, m);
  throw new Error(`skeleton view: no shape for bone "${id}"`);
}

// ---------------------------------------------------------------------------------------------------------------------------------------
// Markers, overlays, picking
const MARKER_R = { // joint marker radius, metres at 1.75 m
  pelvis: 0.020, hip: 0.017, shoulder: 0.017, knee: 0.015, elbow: 0.015, ankle: 0.012, wrist: 0.012, head: 0.012, clavicle: 0.010, forearm: 0.008,
  jaw: 0.007, eye: 0.005, mtp: 0.007, L: 0.0085, T: 0.0060, C: 0.0060, thumb: 0.005, mcp: 0.0055, pip: 0.004, dip: 0.004,
};
function markerRadius(j) {
  if (j.region) return MARKER_R[j.region === "lumbar" ? "L" : j.region === "thoracic" ? "T" : "C"];
  const n = j.id.replace(/_[LR]$/, "");
  if (MARKER_R[n] != null) return MARKER_R[n];
  const m = /_(mcp|pip|dip|cmc|ip)$/.exec(n);
  return m ? MARKER_R[m[1] === "cmc" || m[1] === "ip" ? "thumb" : m[1]] : 0.008;
}
const IMPORTANT = new Set(["pelvis", "head", "hip", "knee", "ankle", "shoulder", "elbow", "wrist", "jaw"]);

function dotTexture(kind, size = 32) {
  // a round dot: "dot" = white with dark outline, "ring" = hollow ring (selection), "com" = checkered circle, "cross" = floor cross
  const d = new Uint8Array(size * size * 4), c = (size - 1) / 2;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const dx = x - c, dy = y - c, r = Math.hypot(dx, dy) / c, i = (y * size + x) * 4;
      let col = null;
      if (kind === "dot") col = r <= 0.55 ? [255, 255, 255, 255] : r <= 0.92 ? [24, 24, 24, 255] : null;
      else if (kind === "ring") col = r >= 0.72 && r <= 0.93 ? [255, 212, 0, 255] : r > 0.93 && r <= 0.99 ? [30, 30, 30, 255] : r >= 0.64 && r < 0.72 ? [30, 30, 30, 255] : null;
      else if (kind === "com") {
        if (r <= 0.95) col = (dx >= 0) === (dy >= 0) ? [20, 20, 20, 255] : [255, 255, 255, 255];
        if (r > 0.82 && r <= 0.97) col = [20, 20, 20, 255];
      } else if (kind === "cross") col = Math.min(Math.abs(dx), Math.abs(dy)) < 1.1 && r <= 0.95 ? [229, 72, 77, 255] : null;
      if (col) { d[i] = col[0]; d[i + 1] = col[1]; d[i + 2] = col[2]; d[i + 3] = col[3]; }
    }
  }
  const t = new THREE.DataTexture(d, size, size, THREE.RGBAFormat);
  t.colorSpace = THREE.SRGBColorSpace;
  t.generateMipmaps = false;
  t.magFilter = t.minFilter = THREE.LinearFilter;
  t.needsUpdate = true;
  return t;
}

/** Pull points slightly toward the camera so that a dot lying on the skin is not swallowed by it (clip space bias). */
function depthBias(mat, amount) {
  mat.onBeforeCompile = (shader) => {
    shader.vertexShader = shader.vertexShader.replace("#include <project_vertex>", `#include <project_vertex>\n gl_Position.z -= ${amount.toFixed(4)} * gl_Position.w;`);
  };
}

export class SkeletonView {
  /**
   * @param {{ body, bones: Map<string, THREE.Bone>, kin: Kinematics, group: THREE.Group, quality?: "high"|"low", com?: (out: Vector3) => {point, mass} }} cfg
   */
  constructor({ body, bones, kin, group, quality = "high", com = null }) {
    this.body = body;
    this.bones = bones;
    this.kin = kin;
    this.group = group;
    this.comFn = com;
    this.q = quality === "low" ? 0.6 : 1;
    this.geos = []; this.mats = []; this.texs = [];
    this.disp = { skeleton: false, joints: true, labels: false, axes: true, landmarks: false, com: false, xray: false, onTop: true };
    this.selected = null; this.highlighted = null;
    this._v = V(); this._w = V();

    // neutral world positions of the joints (cumulative offsets; pelvis at x = z = 0, y = rest height)
    this.W = {};
    for (const j of JOINTS) {
      const o = body.joints[j.id].offset;
      this.W[j.id] = j.parent ? this.W[j.parent].clone().add(V(o[0], o[1], o[2])) : V(0, o[1], 0);
    }
    this.LM = {};
    for (const [id, l] of Object.entries(body.landmarks)) this.LM[id] = this.W[l.joint].clone().add(V(l.offset[0], l.offset[1], l.offset[2]));
    const top = this.LM.vertex ?? this.W.head.clone().add(V(0, 0.138, 0));
    this.stature = top.y;
    this.s = this.stature / 1.75;

    this._boneMeshes = [];
    this._skeletons = new Map(); // skinned bone meshes share one Skeleton per group (the thorax, each forearm)
    this._bonesBuilt = false; // the bone meshes are generated when the skeleton is first shown (or asked for): behind an opaque skin they cost 60-100 ms for nothing
    this.markers = [];
    this._buildMarkers();
    this._buildOverlays();
    this._buildSelection();
    this.setDisplay(this.disp);
  }

  _geo(g) { this.geos.push(g); return g; }
  /** An overlay geometry whose points move every frame: no bounds (an empty Box3 is ignored by Box3.setFromObject, so framing the rig never includes the world origin). */
  _dyn(g) {
    g.boundingBox = new THREE.Box3();
    g.boundingSphere = new THREE.Sphere(new THREE.Vector3(), -1);
    return this._geo(g);
  }
  _mat(m) { this.mats.push(m); return m; }

  // ---- bones ----------------------------------------------------------------------------------------------------------------------------
  /** The 118 bone meshes (generated on first use). */
  get boneMeshes() { this._ensureBones(); return this._boneMeshes; }

  _ensureBones() {
    if (this._bonesBuilt || this._disposed) return;
    this._bonesBuilt = true;
    this._buildBones();
    this.group.updateMatrixWorld(true); // new meshes: their world matrices are needed by the raycaster before anything renders them
  }

  _buildBones() {
    this.boneMat = this._mat(new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.62, metalness: 0, color: 0xffffff }));
    // Bone is a pale material and the light theme a pale background: lit faces came out at 1.03:1 against it and thin bones (ribs, fingers,
    // clavicles) vanished. Silhouette darkening (the colour falls to 38 % where the surface turns away from the eye) draws every bone with an
    // edge in both themes, without a second mesh per bone (an inverted-hull outline would double the 118 draw calls).
    this.boneMat.onBeforeCompile = (sh) => {
      sh.fragmentShader = sh.fragmentShader.replace("#include <normal_fragment_maps>", `#include <normal_fragment_maps>
        diffuseColor.rgb *= mix(0.38, 1.0, smoothstep(0.0, 0.45, abs(dot(normalize(normal), normalize(vViewPosition)))));`);
    };
    this.boneMat.customProgramCacheKey = () => "bone-rim";
    const vg = {};
    for (const id of CHAIN.slice(0, -1)) vg[id] = vertGeom(this.W, id, this.s);
    const ac = this.LM.acromion_L;
    const cs = ac ? Math.min(1.5, Math.max(0.7, Math.abs(ac.x) / (0.1876 * this.s))) : 1; // ribcage breadth follows the shoulder breadth
    const baseCtx = { s: this.s, q: this.q, W: this.W, LM: this.LM, body: this.body, vg, cs };
    for (const def of BONES) {
      const mirror = def.side === "R";
      // left-frame world positions: the right side is built as the mirror image of its own (mirrored back) joints and landmarks
      const fl = (p) => (mirror ? V(-p.x, p.y, p.z) : p.clone());
      const ctx = {
        ...baseCtx, def, mirror,
        end: (e) => fl(e.startsWith("lm:") ? this._lm(e.slice(3)) : this.W[e]),
        J: (n) => fl(this.W[`${n}${mirror ? "_R" : "_L"}`] ?? this.W[n]),
        // landmark of the left-frame name "x_L" -> the side being built ("x_R" for the right, mirrored into the left frame)
        L: (n) => fl(this._lm(mirror && n.endsWith("_L") ? `${n.slice(0, -2)}_R` : n)),
      };
      const m = buildBone(ctx, def);
      let mesh;
      if (m.skin) mesh = this._skinned(m, def, mirror);
      else {
        mesh = new THREE.Mesh(this._geo(m.build(fl(this.W[def.joint]), mirror)), this.boneMat);
        this.bones.get(def.joint).add(mesh);
      }
      mesh.name = `bone:${def.id}`;
      mesh.userData = { boneId: def.id, jointId: def.joint };
      mesh.matrixAutoUpdate = false;
      mesh.visible = !!this.disp.skeleton;
      this._boneMeshes.push(mesh);
    }
    if (this._tint) this._applyTint();
  }

  /**
   * Colour bones with flat colours instead of their anatomical vertex colours: tint = { boneId: sRGB hex | null } (a bone not listed or null keeps its
   * own colours), or null to restore all of them. Used for the RULA / REBA strain view. One material per colour, with the same silhouette darkening.
   */
  setTint(tint) {
    this._tint = tint ?? null;
    if (this._bonesBuilt) this._applyTint();
  }

  _tintMat(hex) {
    this._tintMats ??= new Map();
    let m = this._tintMats.get(hex);
    if (!m) {
      m = this._mat(new THREE.MeshStandardMaterial({ color: hex, roughness: 0.55, metalness: 0, emissive: hex, emissiveIntensity: 0.18 }));
      m.onBeforeCompile = this.boneMat.onBeforeCompile;
      m.customProgramCacheKey = () => "bone-rim";
      this._tintMats.set(hex, m);
    }
    return m;
  }

  _applyTint() {
    const t = this._tint;
    for (const mesh of this._boneMeshes) {
      const hex = t ? t[mesh.userData.boneId] : null;
      mesh.material = hex == null ? this.boneMat : this._tintMat(hex);
    }
  }

  /**
   * A bone mesh skinned between two bones (a rib: its vertebra and the sternum's; the radius: the elbow and the forearm joint; m.skin says which and
   * with what weights). The mesh is parented to its own joint like every other bone mesh and built in the frame of that joint. One Skeleton is shared by
   * all meshes of a group. (In three's attached bind mode the skinned position depends only on the bind matrix, which is the neutral world matrix of
   * the bone the mesh hangs from, and on the bones: where the mesh sits in the hierarchy does not matter.)
   */
  _skinned(m, def, mirror) {
    const sk = m.skin, own = this.bones.get(def.joint);
    this.group.updateWorldMatrix(true, false);
    const G = this.group.matrixWorld;
    let skel = this._skeletons.get(sk.group);
    if (!skel) {
      const Ginv = G.clone().invert(); // the bones' neutral world matrices are a translation to the joint, below the group
      skel = new THREE.Skeleton(sk.ids.map((id) => this.bones.get(id)), sk.ids.map((id) => new THREE.Matrix4().makeTranslation(-this.W[id].x, -this.W[id].y, -this.W[id].z).multiply(Ginv)));
      this._skeletons.set(sk.group, skel);
    }
    const jw = this.W[def.joint], geo = m.build(mirror ? V(-jw.x, jw.y, jw.z) : jw, mirror), n = geo.attributes.position.count, w = sk.weights(); // (built in the left frame: see _buildBones)
    const [a, b] = sk.bones.map((id) => sk.ids.indexOf(id));
    const idx = new Uint16Array(4 * n), wt = new Float32Array(4 * n);
    for (let i = 0; i < n; i++) {
      idx[4 * i] = a; idx[4 * i + 1] = b;
      wt[4 * i] = a === b ? 1 : 1 - w[i]; wt[4 * i + 1] = a === b ? 0 : w[i];
    }
    geo.setAttribute("skinIndex", new THREE.Uint16BufferAttribute(idx, 4));
    geo.setAttribute("skinWeight", new THREE.Float32BufferAttribute(wt, 4));
    const mesh = new THREE.SkinnedMesh(this._geo(geo), this.boneMat);
    own.add(mesh);
    mesh.bind(skel, new THREE.Matrix4().makeTranslation(this.W[def.joint].x, this.W[def.joint].y, this.W[def.joint].z).premultiply(G));
    mesh.frustumCulled = false; // the bounding sphere of a skinned mesh is that of the pose it was last computed in; _pick refreshes it
    return mesh;
  }

  _lm(id) {
    const p = this.LM[id];
    if (!p) throw new Error(`skeleton view: landmark "${id}" is missing`);
    return p;
  }

  // ---- joint markers ---------------------------------------------------------------------------------------------------------------------
  _buildMarkers() {
    const geo = this._geo(new THREE.SphereGeometry(1, this.q < 1 ? 10 : 14, this.q < 1 ? 7 : 10));
    const mk = (hex) => this._mat(new THREE.MeshStandardMaterial({ color: hex, emissive: hex, emissiveIntensity: 0.3, roughness: 0.45, metalness: 0.05 }));
    const byDof = { 0: mk(COLORS.root), 1: mk(COLORS.dof1), 2: mk(COLORS.dof2), 3: mk(COLORS.dof3) };
    // hover: a vivid magenta, which reads on both themes and on the pale bones (white was a blob on the light theme); none of the DOF colours is near it
    this.hiMat = this._mat(new THREE.MeshStandardMaterial({ color: 0xff2d95, emissive: 0xff2d95, emissiveIntensity: 0.55, roughness: 0.35 }));
    this.markerMats = [...Object.values(byDof), this.hiMat];
    for (const j of JOINTS) {
      const r = markerRadius(j) * this.s;
      const mat = j.parent == null ? byDof[0] : byDof[j.dof.length];
      const mesh = new THREE.Mesh(geo, mat);
      mesh.name = `joint:${j.id}`;
      mesh.userData = { jointId: j.id, baseMat: mat, baseR: r };
      mesh.scale.setScalar(r);
      mesh.updateMatrix();
      mesh.matrixAutoUpdate = false;
      this.bones.get(j.id).add(mesh);
      this.markers.push(mesh);
    }
  }

  // ---- world-frame overlays: landmarks, centre of mass --------------------------------------------------------------------------------------
  _buildOverlays() {
    this.overlay = new THREE.Group();
    this.overlay.name = "rig-overlay";
    this.group.add(this.overlay);
    const lmIds = Object.keys(this.body.landmarks);
    this.lmIds = lmIds;
    this.lmPos = new Float32Array(lmIds.length * 3);
    const g = this._dyn(new THREE.BufferGeometry());
    g.setAttribute("position", new THREE.BufferAttribute(this.lmPos, 3));
    const tex = dotTexture("dot");
    this.texs.push(tex);
    this.lmMat = this._mat(new THREE.PointsMaterial({ size: 8, sizeAttenuation: false, map: tex, transparent: true, alphaTest: 0.4, depthWrite: false }));
    depthBias(this.lmMat, 0.004);
    this.lmPoints = new THREE.Points(g, this.lmMat);
    this.lmPoints.name = "landmarks";
    this.lmPoints.frustumCulled = false;
    this.lmPoints.renderOrder = 50;
    this.overlay.add(this.lmPoints);

    const mkPoint = (kind, size) => {
      const gg = this._dyn(new THREE.BufferGeometry());
      gg.setAttribute("position", new THREE.BufferAttribute(new Float32Array(3), 3));
      const t = dotTexture(kind);
      this.texs.push(t);
      const mat = this._mat(new THREE.PointsMaterial({ size, sizeAttenuation: false, map: t, transparent: true, alphaTest: 0.4, depthTest: false, depthWrite: false }));
      const p = new THREE.Points(gg, mat);
      p.frustumCulled = false;
      p.renderOrder = 130;
      this.overlay.add(p);
      return p;
    };
    this.comPoint = mkPoint("com", 20);
    this.comPoint.name = "com";
    this.floorPoint = mkPoint("cross", 14);
    this.floorPoint.name = "com-floor";
    const lg = this._dyn(new THREE.BufferGeometry());
    lg.setAttribute("position", new THREE.BufferAttribute(new Float32Array(6), 3));
    this.comLineMat = this._mat(new THREE.LineBasicMaterial({ color: COLORS.com, transparent: true, opacity: 0.9, depthTest: false }));
    this.comLine = new THREE.Line(lg, this.comLineMat);
    this.comLine.frustumCulled = false;
    this.comLine.renderOrder = 129;
    this.comLine.name = "com-line";
    this.overlay.add(this.comLine);
  }

  // ---- selection ring + triad ----------------------------------------------------------------------------------------------------------------
  _buildSelection() {
    const t = dotTexture("ring", 64);
    this.texs.push(t);
    const g = this._dyn(new THREE.BufferGeometry());
    g.setAttribute("position", new THREE.BufferAttribute(new Float32Array(3), 3));
    this.ringMat = this._mat(new THREE.PointsMaterial({ size: 34, sizeAttenuation: false, map: t, transparent: true, alphaTest: 0.3, depthTest: false, depthWrite: false }));
    this.ring = new THREE.Points(g, this.ringMat);
    this.ring.frustumCulled = false;
    this.ring.renderOrder = 140;
    this.ring.visible = false;
    this.ring.name = "selection-ring";
    this.triad = null; // { group, objects, dofs: [{ key, tip: Vector3 (parent frame), ... }] }
  }

  select(id) {
    this.selected = id;
    this._clearTriad();
    this.ring.removeFromParent();
    if (!id) { this.ring.visible = false; return; }
    const mk = this.markers[JOINTS.findIndex((j) => j.id === id)];
    this.bones.get(id).add(this.ring); // child of the bone (not of the marker): it stays visible when the markers are hidden
    this.ring.position.copy(mk.position);
    this.ring.visible = true;
    this._buildTriad(id);
    this._applyVisibility();
  }

  highlight(id) {
    if (this.highlighted) { const m = this.markers[JOINTS.findIndex((j) => j.id === this.highlighted)]; m.material = m.userData.baseMat; m.scale.setScalar(m.userData.baseR); m.updateMatrix(); }
    this.highlighted = id;
    if (id) { const m = this.markers[JOINTS.findIndex((j) => j.id === id)]; m.material = this.hiMat; m.scale.setScalar(m.userData.baseR * 1.45); m.updateMatrix(); }
  }

  _clearTriad() {
    if (!this.triad) return;
    this.triad.group.removeFromParent();
    for (const o of this.triad.disposables) { o.geometry.dispose(); o.material.dispose(); const gi = this.geos.indexOf(o.geometry); if (gi >= 0) this.geos.splice(gi, 1); const mi = this.mats.indexOf(o.material); if (mi >= 0) this.mats.splice(mi, 1); }
    this.triad = null;
  }

  _buildTriad(id) {
    const j = JOINT_BY_ID[id], s = this.s;
    const attach = j.parent ?? id;
    const local = j.parent ? this.bones.get(id).position.clone() : V(); // position of the joint in the attach bone's frame
    const group = new THREE.Group();
    group.position.copy(local);
    group.name = "joint-triad";
    const disposables = [];
    const own = (obj) => { disposables.push(obj); this.geos.push(obj.geometry); this.mats.push(obj.material); return obj; };
    // local-frame axes: thin rods with a bead at the end (a LineSegments is 1 px wide in WebGL whatever the zoom, and was lost next to the DOF arrows)
    const L = 0.06 * s, am = new Mesher(0.7);
    [[X_, 0xff4d4d], [Y_, 0x3ddc84], [Z_, 0x4d8dff]].forEach(([d, hex]) => {
      const tip = d.clone().multiplyScalar(L);
      am.color(hex);
      am.rod(V(), tip, 0.0018 * s, 0.0018 * s, 0.0018 * s, 0.0018 * s, { capA: 0.3, capB: 0, segs: 6 });
      am.ellipsoid(tip, [0.0034 * s, 0.0034 * s, 0.0034 * s], null, { lat: 4, lon: 6 });
    });
    const axes = own(new THREE.Mesh(am.build(V(), false), new THREE.MeshBasicMaterial({ vertexColors: true, depthTest: false, transparent: true })));
    axes.renderOrder = 135; axes.frustumCulled = false; axes.name = "axes";
    group.add(axes);
    const dofs = [];
    const palette = { swing1: 0xe83e8c, swing2: 0x17c3d6, twist: 0xf5c518 };
    j.dof.forEach((d) => {
      const dir = new THREE.Vector3(...d.moves).normalize(), probe = new THREE.Vector3(...d.probe).normalize();
      const tail = probe.clone().multiplyScalar(0.05 * s), len = 0.065 * s;
      const m = new Mesher(1);
      m.color(palette[d.role] ?? 0xffffff);
      const knee = tail.clone().addScaledVector(dir, len * 0.68), tip = tail.clone().addScaledVector(dir, len);
      m.rod(tail, knee, 0.0022 * s, 0.0022 * s, 0.0022 * s, 0.0022 * s, { capA: 0.2, capB: 0, segs: 6 });
      m.tube([knee, tip], (u) => ({ a: 0.0068 * s * (1 - u) }), { capA: 0, capB: -1, segs: 8, n: 2 });
      const mat = new THREE.MeshBasicMaterial({ vertexColors: true, depthTest: false, transparent: true });
      const mesh = own(new THREE.Mesh(m.build(V(), false), mat));
      mesh.renderOrder = 136; mesh.name = `dof:${d.key}`; mesh.frustumCulled = false;
      group.add(mesh);
      dofs.push({ key: d.key, label: d.label, pos: d.pos, neg: d.neg, role: d.role, color: palette[d.role], tip: tip.clone().addScaledVector(dir, 0.012 * s) });
    });
    this.bones.get(attach).add(group);
    this.triad = { group, disposables, dofs, attach, local };
    group.visible = this.disp.axes;
  }

  // ---- display -----------------------------------------------------------------------------------------------------------------------------------
  setDisplay(d) {
    Object.assign(this.disp, d);
    this._applyVisibility();
    // on top: markers drawn over everything else (x-ray, or no skin to hide them behind); otherwise depth-tested like any surface
    const x = this.disp.onTop ?? !!this.disp.xray;
    for (const m of this.markerMats) { m.depthTest = !x; m.transparent = x; m.needsUpdate = true; }
    for (const m of this.markers) m.renderOrder = x ? 120 : 0;
  }

  _applyVisibility() {
    const d = this.disp;
    if (d.skeleton) this._ensureBones();
    for (const m of this._boneMeshes) m.visible = !!d.skeleton;
    for (const m of this.markers) m.visible = !!d.joints;
    this.lmPoints.visible = !!d.landmarks;
    for (const o of [this.comPoint, this.floorPoint, this.comLine]) o.visible = !!d.com;
    if (this.triad) this.triad.group.visible = !!d.axes;
    this.ring.visible = !!this.selected;
  }

  /** Refresh the world-frame overlays (landmark dots, centre of mass) from the Kinematics. Cheap; called after every pose change. */
  update() {
    const d = this.disp;
    if (d.landmarks) {
      const v = this._v, kin = this.kin, L = this.body.landmarks;
      this.lmIds.forEach((id, i) => { const l = L[id]; kin.toWorld(l.joint, l.offset, v); this.lmPos[3 * i] = v.x; this.lmPos[3 * i + 1] = v.y; this.lmPos[3 * i + 2] = v.z; });
      this.lmPoints.geometry.attributes.position.needsUpdate = true;
    }
    if (d.com && this.comFn) {
      let r;
      try { r = this.comFn(this._w); } catch { return; } // a body without masses: nothing to show
      const p = r.point;
      const a = this.comPoint.geometry.attributes.position; a.setXYZ(0, p.x, p.y, p.z); a.needsUpdate = true;
      const f = this.floorPoint.geometry.attributes.position; f.setXYZ(0, p.x, 0.002, p.z); f.needsUpdate = true;
      const l = this.comLine.geometry.attributes.position; l.setXYZ(0, p.x, p.y, p.z); l.setXYZ(1, p.x, 0.002, p.z); l.needsUpdate = true;
    }
  }

  // ---- picking ---------------------------------------------------------------------------------------------------------------------------------------
  /** three's Raycaster ignores visibility, and a hidden ANCESTOR (a host that hides rig.group, a collapsed sub-tree) hides its children too. */
  _shown(m) {
    for (let o = m; o; o = o.parent) if (!o.visible) return false;
    return m.material.visible !== false;
  }
  _pick(raycaster, meshes, key) {
    let best = null;
    const hits = [];
    for (const m of meshes) {
      if (!this._shown(m)) continue;
      hits.length = 0;
      if (m.isSkinnedMesh) { m.boundingBox = null; m.computeBoundingSphere(); } // the pose has changed since they were computed (see _skinned)
      raycaster.intersectObject(m, false, hits);
      if (hits.length && (!best || hits[0].distance < best.distance)) best = { id: m.userData[key], point: hits[0].point.clone(), distance: hits[0].distance };
    }
    return best;
  }
  // Only what can be seen is pickable: with an opaque skin in front (skin on, no x-ray) the bones and markers are hidden, so they are not hit either.
  /**
   * Joint markers are 4-20 mm spheres: 2-3 px on screen for the spine, the fingers and the toes at the default framing, which no mouse (and
   * certainly no finger) hits. So a marker is also picked when the ray passes within `tolerance` of its centre, measured as a fraction of the
   * height of the view at that distance (0.012 is about 9 px in a 800 px high view); an exact hit on the sphere always wins, then the marker
   * closest to the ray. The tolerance needs raycaster.camera (set by Raycaster.setFromCamera, which viewport.ray does); a hand-made ray hits exactly.
   */
  pickJoint(raycaster, { tolerance = 0.012 } = {}) {
    if (!(this.disp.joints && (this.disp.onTop ?? true))) return null;
    const exact = this._pick(raycaster, this.markers, "jointId");
    if (exact || !(tolerance > 0) || !raycaster.camera) return exact;
    const cam = raycaster.camera, o = raycaster.ray.origin, d = raycaster.ray.direction;
    const span = cam.isOrthographicCamera ? (cam.top - cam.bottom) / (cam.zoom || 1) : 2 * Math.tan((cam.fov * Math.PI) / 360) / (cam.zoom || 1); // view height per unit distance (perspective) or in total (ortho)
    let best = null;
    const c = this._v;
    for (const m of this.markers) {
      if (!this._shown(m)) continue;
      const e = m.matrixWorld.elements;
      c.set(e[12] - o.x, e[13] - o.y, e[14] - o.z);
      const t = c.dot(d);
      if (t < raycaster.near || t > raycaster.far) continue;
      const miss = Math.sqrt(Math.max(0, c.lengthSq() - t * t)), reach = tolerance * (cam.isOrthographicCamera ? span : span * t);
      if (miss <= reach && (!best || miss / reach < best.score)) best = { score: miss / reach, id: m.userData.jointId, point: new THREE.Vector3(e[12], e[13], e[14]), distance: t };
    }
    return best && { id: best.id, point: best.point, distance: best.distance };
  }
  pickBone(raycaster) { return this.disp.skeleton && (this.disp.onTop ?? true) ? this._pick(raycaster, this.boneMeshes, "boneId") : null; }

  // ---- labels ---------------------------------------------------------------------------------------------------------------------------------------------
  labelAnchors() {
    const out = [], d = this.disp;
    if (d.labels) {
      for (const j of JOINTS) {
        out.push({ id: j.id, text: j.label, position: this.kin.position(j.id, V()), kind: "joint", importance: IMPORTANT.has(j.id.replace(/_[LR]$/, "")) ? 1 : j.region ? 0.5 : 0.25 });
      }
      if (d.landmarks) {
        for (const id of this.lmIds) {
          const l = this.body.landmarks[id];
          out.push({ id: `lm:${id}`, text: l.label ?? id, position: this.kin.toWorld(l.joint, l.offset, V()), kind: "landmark", importance: 0.3 });
        }
      }
    }
    if (this.triad && d.axes) {
      // The labels of the DOF arrows of a selected joint are fanned out around the joint in WORLD space instead of sitting on the arrow tips:
      // the tips of a 3-DOF joint are 5-6 cm apart, 10-15 px at the default framing, so the names (pinned, never dropped by the overlay) were
      // stacked on each other and on the joint's own name. The fan puts each name on its own level (the overlay draws a label to the right of
      // its anchor, so what separates two of them in every view but the top one is the height) and on its own side of the joint (which
      // separates them in the top view); a stack of 12 cm steps clears the 18 px labels at the default framing.
      const n = this.triad.dofs.length, J = this.kin.position(this.selected, V()), s = this.s;
      const level = [[1], [1, -1], [1, -1, -2]][Math.min(n, 3) - 1]; // steps above (+) or below (-) the joint's own name
      this.triad.dofs.forEach((dof, k) => {
        const a = Math.PI / 2 + (2 * Math.PI * k) / Math.max(n, 1);
        const at = J.clone().add(V(0.08 * s * Math.cos(a), 0.12 * s * (level[k] ?? -2), 0.08 * s * Math.sin(a)));
        out.push({ id: `dof:${this.selected}:${dof.key}`, text: dof.key, position: at, kind: "dof", importance: 2, color: dof.color, detail: `${dof.label}: + ${dof.pos}` });
      });
    }
    return out;
  }

  // ---- lifecycle ---------------------------------------------------------------------------------------------------------------------------------------------
  dispose() {
    this._clearTriad();
    this.ring.removeFromParent();
    this._disposed = true;
    for (const m of this._boneMeshes) m.removeFromParent();
    for (const k of this._skeletons.values()) k.dispose();
    this._skeletons.clear();
    for (const m of this.markers) m.removeFromParent();
    this.overlay.removeFromParent();
    for (const g of new Set(this.geos)) g.dispose();
    for (const m of new Set(this.mats)) m.dispose();
    for (const t of this.texs) t.dispose();
    this.geos = []; this.mats = []; this.texs = []; this._boneMeshes = []; this.markers = [];
  }
}
